window.GAME_DATA = {"scenes": {"title_hint": {"bg": "washroom_mirror", "text": ["（这是一个关于「后悔」的故事。）", "（你只有十八分钟。——当然，真正的玩家知道：游戏没有倒计时。）", "（除非你选择交出名字。）"], "choices": [{"t": "开始游戏", "go": "arrive"}]}, "arrive": {"title": "序章 · 古城的背面", "text": ["你叫杨小天，十八岁，刚考完DSE，独自来到云南大理。", "同学问你为什么一个人。你说想静一静。", "其实你只是害怕他们谈考试、对答案、讨论哪一科失手。更可怕的是他们完全不谈考试——喝酒、唱歌、回忆六年中学生涯的趣事，而其中许多回忆都没有你。", "因为那些时候，你通常在补习。", "「沐山月」民宿藏在步行街转进去五十米的小巷里。五十米很短，却像两个世界：巷外是银饰店、旅拍和歌手；巷内，白墙灰瓦，门口两盏暖黄的灯。"], "choices": [{"t": "习惯性打开手机，核对大学入学分数表格", "go": "hotel", "fx": {"regret": 1, "flags": {"planner": 1}}, "hint": "你最擅长的事：把所有不安变成数字"}, {"t": "收起手机，安静地看一会儿山", "go": "hotel", "fx": {"human": 1}, "note": "大理的山不急，仿佛已经等了你很久"}], "art": "street_modern"}, "hotel": {"text": ["柜台后的女孩看了一眼你的回乡证。「一个人？高中毕业？那应该很轻松了。」", "你笑了笑。每一个大人都以为考完试就会轻松——就像每一个站在岸上的人，都觉得溺水的人只要不再游动，就能休息。", "房卡递过来，下面挂着一块半月形黄铜牌，边缘磨得很光滑。「二楼，七号房。十一点以后，我们会锁外面的木门。」", "你注意到柜台后挂着一张黑白照片：同样的院门，同样的石阶，同样的一棵树。树下站着七个人——", "那七个人都没有看镜头。他们看着二楼，看着你即将入住的七号房。"], "choices": [{"t": "问女孩：「他们为什么都看着楼上？」", "go": "photo", "fx": {"flags": {"photo_clue": 1}}}, {"t": "很累，不追问了。上楼", "go": "room7"}], "art": "reception"}, "photo": {"text": ["「可能是以前的住客吧。」女孩凑近看了看照片，脸上的笑容忽然淡了一点。「我以前没留意。」", "她伸手想把照片取下来。刚碰到相框——照片里忽然闪过一道白光，像相机的闪光灯。", "她吓了一跳，立刻缩手。两人安静了几秒。", "「玻璃反光。」她说。", "你回头看了一眼身后。民宿大门外一片漆黑。没有汽车，也没有相机。", "哪里来的反光？"], "choices": [{"t": "没有继续追问。上楼", "go": "room7"}], "art": "item_photo_bw"}, "room7": {"art": "room_window", "text": ["七号房不大，却收拾得很舒服。推开窗，能看见院子里那棵梅树。", "梅树上没有花。树枝被夜风吹动，轻轻敲着窗沿。一下。一下。像有人站在外面敲门。", "母亲已经发来五条信息：到了没有、不要乱吃东西、晚上不要独自走太远、一张天气预报截图。", "第五条只有六个字：「不要一直想成绩。」", "备忘录里躺着你早已整理好的表格：A方案，成绩理想；B方案，稍低于预期；C方案，严重失手。每个方案下面都有大学、专业、起薪和申请成功率。", "数字不会安慰人。但数字看起来可以控制。"], "choices": [{"t": "回复母亲：「知道。返嚟飲湯。」", "go": "night", "fx": {"human": 1, "flags": {"mom_msg": 1}}}, {"t": "更新其中一个专业的录取概率", "go": "night", "fx": {"regret": 1, "flags": {"planner": 1}}}, {"t": "关掉所有屏幕，直接出门", "go": "night"}]}, "night": {"bg": "key_visual", "title": "第一章 · 背面与正面", "text": ["古城的夜色比白天更热闹。歌手抱着吉他，唱着每个人仿佛都听过、又叫不出名字的歌。一个喝醉的男人坐在路边哭，朋友不安慰，只是陪他坐着。", "走过一间跆拳道馆时，你停了下来。玻璃门上贴着比赛照片：十几个孩子，有人拿奖牌，有人扮鬼脸；教练没看镜头，低头替一个小孩整理腰带。", "你也有一条黑带。十三岁那年，你在比赛最后十秒反胜，教练把你整个人抱起来。那曾经是你最快乐的一天。", "后来你每周少练一次，再变成每月一次，最后对教练说：要暂时停一年。", "教练没有劝你。只说了一句：「暂时停下来的东西，通常不会自己重新开始。」"], "choices": [{"t": "在道馆门前站久一点", "go": "flower", "fx": {"human": 1, "flags": {"blackbelt": 1}}}, {"t": "移开目光，继续走", "go": "flower", "fx": {"regret": 1, "flags": {"blackbelt": 1}}}], "art": "ch06_market_night"}, "flower": {"text": ["「哥哥。」一个七八岁的小女孩拉着你的衣袖，手里捧着几朵玫瑰。「给女朋友买一朵花吧。」", "「我没有女朋友。」", "她上下打量你：「那给自己买。」", "「为什么要给自己买花？」", "她想了想，回答得太认真：「因为没有人买给你。」"], "choices": [{"t": "买一朵。二十元，毫无用途，不能增加任何录取概率", "go": "washroom_need", "fx": {"human": 1, "inv": {"rose": 1}}}, {"t": "买下那朵边缘发黑的花，也买下海边合照里、画在空位上的那只丑乌龟", "go": "washroom_need", "fx": {"human": 1, "regret": -1, "inv": {"rose": 1}, "flags": {"turtle": 1}}, "req": {"flag": "planner"}, "note": "你记不起那堂补习课教过什么，只记得那只乌龟"}, {"t": "摇头走开", "go": "washroom_need", "fx": {"regret": 1}}], "art": "girl_rose"}, "washroom_need": {"text": ["十点三十七分，你开始找洗手间。", "拐进一条小巷，只隔一道墙，音乐和灯光便忽然远了。墙角堆着破木板、碎砖、黑色垃圾袋；几根钢筋从拆了一半的墙壁里伸出，像死去动物的肋骨。", "你回头。身后不足二十米，就是灯火通明的步行街。没有人把镜头转向这边。", "你忽然觉得：一条街有正面，也有背面。人也一样。成绩单、奖状、录取通知书，是给别人看的正面；至于为了这些东西放弃过什么——那些都被藏在后巷。", "公厕在巷子尽头，门上的蓝色标志已经褪色。你进去前看了一眼手机：十点四十二分。"], "choices": [{"t": "进去", "go": "mirror"}], "art": "back_alley"}, "mirror": {"bg": "washroom_mirror", "text": ["里面没有人。最里面的水龙头关不紧。滴。滴。滴。", "你洗手的时候，面前那块布满水渍的镜子忽然闪了一下。", "镜中的你还站在那里。镜中的背景却变了——雪白的瓷砖不见了，身后是一面发黑的土墙，墙上插着一支火把。", "你猛然回头。仍然是瓷砖。仍然是惨白的灯。再看镜子，镜子也恢复正常。", "「太累了。」你低声说。没有人回答。", "你关掉水龙头。水滴声却没有停止，而且越来越响。", "不像水。像血滴在石板上。"], "choices": [{"t": "盯着镜子，一步不退", "go": "cross", "fx": {"courage": 1, "flags": {"stared": 1}}, "note": "你在等它再变一次"}, {"t": "转身离开洗手间，回民宿", "end": "E0", "note": "一个刚考完DSE的人，不会轻易相信奇迹"}], "art": "washroom_mirror"}, "cross": {"text": ["你没有再看镜子。你转身走了出去。", "门外没有灯。没有步行街的音乐。没有游客的谈笑声。连那一堆建筑废料也不见了。", "同一条小巷，变成了泥地。两旁是低矮的木屋，屋檐下挂着摇晃的纸灯笼。空气里混着柴烟、马粪和某种烧焦的气味。", "你站在门口，手中仍然拿着那朵玫瑰——花瓣已经完全枯萎。", "你的第一个念头不是穿越。你想的是整蛊节目、电影拍摄，还有云南某种收费昂贵的沉浸式旅游项目。", "然后，远处传来马蹄声。很急。"], "choices": [{"t": "继续", "go": "corpse"}], "art": "old_town_gate"}, "corpse": {"bg": "alley_riders", "title": "第二章 · 死人身上的东西", "art": "horse_lanterns", "text": ["一个人从黑暗中冲出来，胸口全是血，双手死死抓住你的肩膀。", "「救护车……叫救护车！」", "他抬起头。那张脸沾满鲜血，大约二十三四岁，比年长几岁——", "却像你。", "他望着你，眼神里没有惊讶，只有一种等待了很久、终于得到证实的疲倦。他开口，说的是粤语：「终于……来了。」", "「你是谁？」", "他的身体往下沉。「不要相信……」「不要相信谁？」「晏归迟。」", "他的手松开了。你摸他的颈侧：没有脉搏。", "马蹄声越来越近，巷口出现火光。你本来应该立刻逃走。但你看见他衣袋里露出一角卡片——一张香港身份证。", "照片上的人，正是眼前这名死者，也像几年后的你。姓名栏写着三个字：杨小天。出生日期和你完全相同。", "尸体忽然又动了一下，抓住你拿身份证的手，用最后一丝力气说：", "「这是……第七次。」", "随后，他真的死了。你跪在十五世纪的大理古城里，手中拿着自己的身份证。手机屏幕忽然亮了——时间仍然是：十点四十二分。"], "choices": [{"t": "把身份证塞进自己裤袋", "go": "riders", "fx": {"inv": {"idcard": 1}, "flags": {"has_id": 1}}, "note": "不是贪心，是害怕。你想知道这个人是谁，也想知道自己会不会变成他"}, {"t": "把身份证放回他手上。死人的东西，应该留在死者身上", "go": "riders", "fx": {"human": 1, "flags": {"left_id": 1}}}]}, "riders": {"text": ["火光照进巷口。五匹马，马上五人，深色短衣，腰间带刀。刀是真的——刀刃上甚至有血。", "领头的男人约四十岁，左脸一道长疤，从眼角延伸到嘴边。他先看尸体，再看你。那目光不是警察看疑犯，是屠夫看一块还没决定怎么切的肉。", "他说了一句话，你只听懂最后两个字：「同党」。", "一名军士举着火把照向公厕——里面已经没有瓷砖、镜子与水龙头，只剩一面倾斜的土墙，墙下腐烂的木板长满青苔，荒废了几十年。", "你仍然在心里等待某个人喊「停」。没有人出来。这个世界安静得令人害怕。", "刀疤男人蹲下搜身：无线耳机被他捏碎，只剩细小电路板。他抬头：「没有。」军士说：「会不会已交给这妖人？」", "五个人一起看向你。"], "choices": [{"t": "坦白：「他抓着我，只说了两句话。」（隐瞒「晏归迟」三个字）", "go": "demand", "fx": {"wisdom": 1, "flags": {"hid_warning": 1}}}, {"t": "全盘托出：「他说不要相信晏归迟！」", "go": "demand", "fx": {"courage": 1, "flags": {"told_name": 1}}}, {"t": "掏出手机，按亮手电筒对准他们的眼睛", "go": "flashlight", "fx": {"batt": -2, "flags": {"used_light_early": 1}}, "req": {"inv": "phone"}, "note": "妖术？在这里，你就是妖"}], "art": "knife_offer"}, "demand": {"text": ["刀疤男人慢慢走近。「交出来。」「什么？」「他给你的东西。」", "你看向那块被火把照亮的泥地，忽然明白：对方从来没有打算放过你。交不交，都会死。区别只是快一点，还是慢一点。", "「交出来，我让你死得快些。」", "你伸手摸向裤袋——里面有手机、民宿房卡。房卡下方，那块半月形黄铜牌忽然变得很热，像一块刚从火里取出的炭。"], "choices": [{"t": "把热得发烫的铜牌扔向反方向，引开注意", "go": "chase", "fx": {"wisdom": 1, "flags": {"threw_plaque": 1}}}, {"t": "握紧铜牌不放手", "go": "chase", "fx": {"courage": 1, "batt": 0}, "note": "你不明白它为什么烫，但你不想放手"}, {"t": "投降。把一切都交出去", "end": "E1"}], "art": "knife_offer"}, "flashlight": {"text": ["刺眼的白光亮起。五匹马同时受惊。人喊，马叫，一匹马把背上的军士摔了下来。", "「妖术！」不知是谁喊了一声。", "场面顿时混乱。你转身就跑。"], "choices": [{"t": "跑", "go": "chase"}], "art": "phone_flash"}, "chase": {"text": ["你在大理古城走了一个晚上，却完全不认识眼前这座城。没有步行街，没有酒吧，只有交错的泥路、木屋和没有窗户的高墙。", "只能选择看起来最黑的方向。", "背着书包在运动场跑步，和穿过十五世纪的泥地逃命，是两回事。你撞翻木桶，踩进污水，鞋底一滑，整个人撞在墙上。", "「在那边！」两名军士从巷口冲进来。其中一人搭箭，拉弦。", "那一刻，你没有听见声音，也没有感到害怕。脑袋里一片空白。", "弓弦松开——"], "choices": [{"t": "一块瓦片从屋顶砸落，正好击中弓手", "go": "yue", "fx": {"courage": 1}}, {"t": "你下意识侧身，箭擦过耳边钉进木柱", "go": "yue", "fx": {"courage": 1, "flags": {"reflex": 1}}, "req": {"flag": "blackbelt"}, "note": "身体比脑袋更快作出反应"}, {"t": "你僵在原地，来不及躲", "end": "E1", "req": {"stat": {"courage": "<2"}}}], "art": "mud_escape"}, "yue": {"title": "屋顶上的少女", "art": "ayue_pov_roof", "text": ["「上来！」屋顶有人低喝。是个女人的声音。", "屋檐上趴着一个十七八岁的少女：深蓝色窄袖衣服，头发用布带束起，半边脸沾着黑灰，只露出一双很亮的眼睛。她放下一条绳索。", "「拉我！」——她没有拉。「自己爬。」「我不会！」「那就在下面等死。」", "你踩着墙面往上爬，像一只第一次学爬树的熊。她嫌你太慢，最后伸手抓住你的手腕——她的手不大，力气却大得惊人。", "一支箭射中你的背包。她看也不看：「你可以下去拿。」", "你在屋顶上跟着她跑，学她踩木梁承重的位置，却踩碎了两块瓦。「轻一点。」「你不早说？」「我以为你看得出来。」"], "choices": [{"t": "跨过近两米宽的巷子：跳！", "go": "rooftop2", "fx": {"courage": 1}, "note": "「太远了！」「箭更快。」"}, {"t": "助跑、起跳——半空中想起十四岁那年练过的腾空侧踢", "go": "rooftop2", "fx": {"courage": 1, "trustA": 1, "flags": {"jump_style": 1}}, "req": {"flag": "blackbelt"}}]}, "rooftop2": {"text": ["你的双手抓住对面屋檐，身体撞在墙上。她抓住你的衣领把你拖了上去。", "「你比上一个差。」她说。你喘着气：「什么上一个？」她没有回答。", "追兵爬上屋顶。她踢开一根横放的木杆，十几个竹筐一起滚下，把最后一名军士连人带筐摔进小巷。", "「他会不会死？」「你担心他？」「我只是不想有人死。」", "少女看了你一眼：「你来错地方了。」"], "choices": [{"t": "跟上她，跳进染坊院子", "go": "cellar"}], "art": "rooftop_leap"}, "cellar": {"title": "地窖", "text": ["院内十几个巨大的染缸，空气刺鼻。她掀开角落的木板，露出一条仅容一人通过的暗道。", "「进去。」「你是谁？」「救你的人。」「为什么救我？」「因为你还不能死。」", "这个答案并没有让人安心。", "她拔出短刀，刀尖停在你胸前：「现在进去，或者我把你扔出去。」「其实你可以说得客气一点。」「我试过。对上一个没有用。」", "又是上一个。你钻进暗道。"], "choices": [{"t": "进去前先问清楚：「上一个是谁？」", "go": "cellar2", "fx": {"wisdom": 1, "flags": {"asked_prev": 1}}}, {"t": "进去。活着比较重要", "go": "cellar2", "fx": {"regret": 1}}], "art": "dye_vats"}, "cellar2": {"bg": "washroom_mirror", "text": ["暗道潮湿，两旁堆着木箱和陶罐，深处传来流水声。她点亮一盏小油灯。", "确认没有追兵，她停下来：「东西呢？」「什么东西？」「死人给你的东西。」「所有人都在找？」", "「把衣袋里的东西全部拿出来。」你掏出钱包、八达通、手机、充电宝，最后是那块房卡——半月形铜牌离开衣袋时，温度已经恢复正常。", "她看见铜牌，脸色骤然变了，一把抢过去。正面刻着「沐山月」，背面是数字「七」。", "「沐山驿早就荒废了。」她说。「我一个小时前才办理入住。」", "你把身份证拿出来：「你认识这个人吗？」她没有惊讶。这比惊讶更可怕。", "「果然是他。」「你认识他？」「见过一次。他是杨小天。」「我也是杨小天。」「我知道。」", "她从木箱底取出一张发黄的纸，边缘沾着血。纸上画着六张脸——全部都是杨小天。有人年轻，有人年长，一个穿学士袍，一个留胡子，还有一个，已经老了。六张脸下面各写着一个日期。最早的在三个月前，最新的，就是今晚。", "「他是第六个。」她说，「第六个来到这里的杨小天。」"], "choices": [{"t": "「这里是什么年代？」", "go": "ming_reveal"}, {"t": "「你叫什么名字？」", "go": "ming_reveal", "fx": {"human": 1, "trustA": 1}}], "art": "cellar_lamp"}, "ming_reveal": {"text": ["「大明景泰元年。」", "你的历史并不好。但「景泰」两个字，你至少在电视剧里听过。公元一四五零年。", "你靠着石壁慢慢坐下来。「大理国？」「这里现在还是大理国？」", "她看你的眼神第一次出现明显变化——不是惊讶，是同情，像在看一个脑袋不太好的人。", "「大理国早已亡了。蒙古人灭的，已近二百年。这里是大明的大理府。」", "你坐在十五世纪的地窖里，用一部时间停止的手机，试图接受自己并没有穿越到想象中的大理国。", "「你叫什么名字？」「段阿月。」「你认识晏归迟吗？」"], "choices": [{"t": "继续", "go": "an_appear"}], "art": "lantern_face"}, "an_appear": {"bg": "yanguichi", "title": "第三章 · 会说粤语的古人", "art": "dark_voice", "text": ["油灯的火焰突然跳了一下。阿月脸上的神情消失了。", "「谁告诉你这个名字？」「死掉的那个我。他说：不要相信晏归迟。」", "她沉默了很久。「这句话，他说对了一半。你确实不能相信晏归迟。但死人没有告诉你另一半——晏归迟也姓杨。他说，他才是真正的杨小天。」", "油灯忽然熄灭。黑暗中，暗道另一头传来一个男人的声音。温和，平静，说的却是标准得不能再标准的、带着香港人特有懒散的粤语：", "「阿月。我不是叫你看见第七个以后——立刻带他来见我吗？」"], "choices": [{"t": "后退半步，挡在阿月前面", "go": "an_talk", "fx": {"courage": 1, "trustA": 1}, "note": "你不确定她在骗你，还是他在骗你。但你在骗与被骗之间，选择了先保护眼前人"}, {"t": "站在原地不动，直视黑暗中的声音", "go": "an_talk", "fx": {"courage": 1}}, {"t": "「你就是晏归迟？」大声问出来", "go": "an_talk", "fx": {"suspA": 1, "flags": {"revealed": 1}}}]}, "an_talk": {"text": ["啪。一簇小小的火焰出现在男人手里——打火机。银色金属外壳满是刮痕。他用它点亮油灯，又是「啪」的一声。在十五世纪的大理地窖里，这个声音比雷声更奇怪。", "他大约五十岁，两鬓灰白，灰色长袍很旧，袖口却十分干净。最特别的是他的眼睛——平静得仿佛眼前发生的一切，他早已看过很多次。", "他看着你的脸，像离家多年的人终于看见一件属于从前的东西。「比我想象中还年轻。」", "「我以前也叫杨小天。」", "阿月突然冲上前，短刀直刺他的胸口。刀尖停在距离他胸口不到半寸的地方——不是她手下留情，是他握住了刀身，鲜血从指缝流下。", "「杀我很容易。」他说，「找到真相以后再杀，也不迟。」"], "choices": [{"t": "「先处理眼前的事。外面的人还在追。」", "go": "an_deal", "fx": {"wisdom": 1}}, {"t": "追问阿月父亲的死：「你害死她的父亲？」", "go": "an_deal", "fx": {"trustA": 1, "suspA": 1}}, {"t": "追问六具尸体：「前六个杨小天，都是你杀的？」", "go": "an_deal", "fx": {"suspA": 1, "flags": {"accused": 1}}}], "art": "lighter"}, "an_deal": {"text": ["男人——晏归迟——转向你，用粤语问：「你的手机还有多少电？」", "你看了眼：百分之二十。", "「开飞行模式，关掉蓝牙，屏幕亮度调到最低。」「这里没有信号，开不开有什么分别？」「你很快就会用到最后一点电。」「用来做什么？」「回家。」", "「你到底是谁？」「我已经回答过。」「我不相信。」", "他竟点了点头：「很好。继续保持。」", "「你见过前面六个我。他们告诉过你我的事。所以你知道我的名字、手机和跆拳道，都不能证明什么。」", "那双疲倦的眼睛里第一次出现别的东西，像是欣慰，又像是悲哀：「你比前面几个更小心。」"], "choices": [{"t": "「他们几岁？他们怎么死的？」", "go": "gas", "fx": {"wisdom": 1, "flags": {"know_six": 1}}}, {"t": "「第六个的死，是不是你造成的？」", "go": "gas", "fx": {"courage": 1, "suspA": 1}}, {"t": "先答应保存电量，留一分信任", "go": "gas", "fx": {"human": 1, "flags": {"trust_an_early": 1}}}], "art": "cellar_three"}, "gas": {"text": ["晏归迟忽然举起右手：「别出声。」", "他俯身把手掌贴在地面，片刻后吹熄油灯。黑暗重新笼罩地窖。", "「来了七个人。地面三个，暗道四个。」「他们怎么找到这里？」「血。杨小天的鞋底沾了血。」", "你低头——白色运动鞋上有一片暗红，是刚才跪在尸体旁沾上的。一路逃进暗道，血迹一路留下。", "「所以我以前叫你们立刻来找我。」他说。「你也没有告诉我原因。」「我说过很多原因。」「你没有说血！」——阿月的声音压得极低，却字字冒火。", "「因为前六次都没有血。」「前六次？」他停顿了一下：「以后再解释。」", "追兵的火光已经出现在暗道转角。晏归迟推开一个木箱，石壁缓缓移开，后面还有一条路。", "「这条路通向哪里？」「沐山驿。」「那里已经荒废。」「荒废的地方才安全。」「如果你想杀我们呢？」「我想杀你们，不必等到现在。」"], "choices": [{"t": "先进。后面的人已经拔刀了", "go": "gas2", "fx": {"courage": 1}, "note": "简单的选择，不需要计算成功率"}, {"t": "问清楚再走：「『前六次』是什么意思？」", "go": "gas2", "fx": {"wisdom": 1, "batt": -1}, "note": "他吹熄了最后一盏灯，什么也没回答。你只能跟进去"}], "art": "ear_on_ground"}, "gas2": {"text": ["三人钻进石壁后的通道。石壁合拢只剩一道缝隙时，一只手突然伸进来——黑色皮护腕，是那个刀疤男人。刀锋随后刺入缝隙，卡住石门。", "一只眼睛出现在石缝外。他隔着缝看见你，嘴角慢慢露出笑容：「七号。我们又见面了。」", "晏归迟从衣袖取出一个很小的黑色圆筒递给你：「扔准一点。」圆筒末端拔出一根金属针，冒出白烟。", "「这不会是——」「会。」「你从哪里弄来的？」「以后。」", "你把圆筒扔出去。一秒。两秒。没有爆炸。外面有人笑了。", "「坏了？」「过期一百多年。」晏归迟说，「很正常。」「你不早说？」「我也刚知道。」", "下一刻，暗道里轰然亮起刺眼的白光。大量白烟喷出。追兵惨叫。", "「推！」石壁轰然合拢。黑暗中你闻到一股熟悉又刺鼻的气味。「催泪弹？」「改装过。」「你说它过期一百多年？」「只过期一百零六年。」"], "choices": [{"t": "继续", "go": "mushan"}], "art": "smoke_flask"}, "mushan": {"bg": "burning_inn", "title": "沐山驿", "art": "dead_plum", "text": ["出口藏在一口枯井里。井外是一座荒废的院子：白墙灰败，屋顶塌了一角，院子中央有一棵歪斜的梅树。", "没有花。树枝被风吹动，轻轻敲着二楼窗沿。一下。一下。", "你完全忘记了呼吸。你来过这里。一模一样的院子、木门，连石阶旁边那道像闪电的裂缝都没变。只是更旧，更荒凉。", "正门上方挂着一块腐烂的木匾，依稀可辨三个字——沐山驿。少了一个月亮。", "二楼最右边，七号房的位置。那扇窗关着。窗纸后面，有灯光。", "「里面有人？」「有。谁？」晏归迟从怀里拿出一把很旧的铜钥匙，下面同样挂着半月形铜牌：数字「一」。", "两个半月形铜牌同时发出微弱的热。", "「你不是想知道前面六个杨小天为什么会死吗？答案就在七号房。」"], "choices": [{"t": "握住门把。自己决定", "go": "hospital", "fx": {"courage": 1}, "note": "「要不要进去。」「里面有什么？」「你的未来。」「哪一个未来？」「全部。」"}, {"t": "先问：「开门的代价是什么？」", "go": "hospital", "fx": {"wisdom": 1}}, {"t": "不进去。转身走", "end": "E1", "req": {"stat": {"courage": "<2"}}}]}, "hospital": {"bg": "hospital_2056", "title": "第四章 · 未来并不值钱", "art": "hospital_2056", "text": ["房门后面不是古代客房。是香港的医院。", "惨白的墙，消毒药水的气味，心电监护仪规律的声响。病床上躺着一个女人——你的母亲，比现在苍老许多，戴着氧气面罩，双眼紧闭。", "病床旁边没有人。只有一部手机，屏幕上显示着十七通未接来电。来电人只有三个字：杨小天。", "墙上的电子钟：2056年7月19日，晚上10点42分。", "监护仪忽然发出持续不断的长鸣。心跳停止了。", "一个穿黑色西装的中年男人从病床另一边缓缓站起。你看不清他的脸，但你看见他的右脚——脚踝内侧，一道月牙形的旧疤。十三岁那年，九龙湾的比赛，护具边缘割破皮肤。那道疤只有你和父母知道。", "他用你的声音说：「你终于肯回来了。」"], "choices": [{"t": "继续", "go": "hosp_talk"}]}, "hosp_talk": {"text": ["「你是谁？」「你以后可能会变成我。」", "你首先问出口的，居然是：「我考进大学了吗？」「考进了。你最想进的那一间。」「读了什么？」「你当时认为最有前途的专业。」「赚到钱了吗？」", "中年男人笑了：「很多。」", "每一个答案都正确。组合起来，却变成了眼前这间病房。", "「既然什么都有，为什么她死的时候，你不在？」「我在苏黎世。签约。一份价值超过四十亿港元的合约。」", "「医生说，她还有两三天。合约只差最后一步，我准备了七年。」「你可以改期。」「对方不会等。」", "你想说「那就不要签」。嘴唇动了动，却没有发出声音。", "「十八岁的人，总觉得未来很值钱。所以你们拿睡眠去换，拿朋友去换，拿喜欢的东西去换，拿所有人以为还有很多的时间去换。」「后来呢？」「后来你会发现，未来和现在一样。它不会因为来得迟，就比较珍贵。」"], "choices": [{"t": "「她等了多久？」", "go": "hosp_seven", "fx": {"human": 1}}, {"t": "「我可以改变这件事吗？」", "go": "hosp_seven", "fx": {"regret": 1}}, {"t": "沉默。不敢问", "go": "hosp_seven", "fx": {"courage": -1, "regret": 1}}], "art": "missed_calls"}, "hosp_seven": {"text": ["「她等了三天。我第四天回来。」「所以你叫归迟？」", "他拿起那部手机递给你。母亲最后一条信息只有一行字：", "「不用赶，做完你的事再回来。」", "「她是不是在怪你？」「不是。」「那你为什么——」「如果她怪我，我反而会好过一点。」", "「我可以改变这件事吗？」「可以。回去。回到十八岁。」「我现在就是十八岁。」「所以所有人都在找你。」", "中年男人终于走进灯光。那张脸被时间、痛苦和无数次选择重新修改过，但右眼下方那颗小痣，和你一样。", "「你是我。」「我曾经是。」"], "choices": [{"t": "握住母亲伸出来的手", "go": "hosp_haunt", "fx": {"human": 1, "flags": {"held_hand": 1}}, "note": "很冷。她的手从被子下面伸出，轻轻抓住你的手腕"}, {"t": "听中年男人的话：「不要碰她」", "go": "hosp_haunt", "fx": {"wisdom": 1, "regret": 1}}], "art": "missed_calls"}, "hosp_haunt": {"text": ["病床上的女人没有睁眼，嘴唇却动了，用粤语轻声问：「小天，返嚟食饭未？」", "你的眼泪一下子涌出来。「返。我返。我现在就返。」", "中年男人脸色骤变：「放手！」「你刚才说她死了！她为什么会说话？」「因为这不是她。」", "女人睁开眼睛。眼睛里没有瞳孔，只有一片惨白。她抓住你的手突然收紧，力气大得不像一个垂死的老人。「返嚟。」声音不再像母亲——像很多人的声音重叠在一起。", "病床下传来抓挠声。六个人从病床下面爬出来：学士袍、跆拳道服、昂贵的黑色西装、胸口染血的黑色运动外套。六张脸，全部都是杨小天。", "刚才死在小巷里的二十三岁杨小天抬起头，脖子以不自然的角度歪向旁边：「第七个。留下来。」", "六个人同时扑向你。中年男人用力将你推开：「醒来！」"], "choices": [{"t": "被六个自己拖住时，回头看清每一张脸", "go": "wake", "fx": {"courage": 1, "wisdom": 1}, "note": "他们不是鬼。他们是答案"}, {"t": "闭眼，挣脱", "go": "wake"}], "art": "under_bed"}, "wake": {"text": ["你睁开眼睛。仍然躺在沐山驿的七号房里。门外是十五世纪的大理夜色。", "阿月站在你身边，短刀出鞘。晏归迟站在门口，受伤的右手仍在滴血。仿佛刚才只过去了一瞬间。", "「妈？」没有人听懂这个字。", "房间中央只有一面几乎和人一样高的铜镜，布满裂纹，镜面漆黑，照不出任何人的影子。", "你抓住晏归迟的衣领：「是你让我看见的？」「我打开了门。」「那间病房是什么？」「一个未来。某一个杨小天的未来。」", "「前六个听完答案以后，全部做了同一个选择：回去。」「他们想回家有什么错？」「没有错。」「那他们为什么会死？」", "他望向黑色铜镜：「因为那东西最喜欢想回家的人。」"], "choices": [{"t": "看镜子", "go": "mirror_keys"}], "art": "dusty_room"}, "mirror_keys": {"bg": "blood_mirror", "title": "第五章 · 第三把钥匙在流血", "art": "mirror_frame", "text": ["铜镜的镜框上刻着七个半月形凹槽。前六个已经嵌入黄铜牌。一。二。三。四。五。六。最后一个凹槽是空的。", "你低头看手中的七号铜牌——大小完全吻合。", "晏归迟伸出手：「给我。」「你以为我还会相信你？」「你本来就不应该相信我。它如果留在你身上，外面的人会一直找到你。」「为什么？」「七块月钥使用同一块陨铁铸成。彼此接近时会发热，山月盘也能感应它们的位置。」", "墙边的木柜后藏着六个长方形木盒：港大学生证、绣着你名字的黑带、结婚戒指、一张小孩蜡笔画——画里的女人、小女孩，和一个没有画脸的「爸爸」、一张2047年的报纸，头版：香港企业家因飞机失事身亡，名字仍然是杨小天。", "第六个盒子是空的。「第六个人的东西呢？」「被人拿走了。一块镜片。可以让一个人看见自己没有选择的人生——也可以让他走进去。」", "阿月忽然说：「那间病房，是他的记忆。」——她看着晏归迟。他没有否认。", "就在这时，你的口袋里的手机震动了。", "没有信号的屏幕上，出现一个来电。来电显示不是号码，是三个字：杨小天。"], "choices": [{"t": "接听", "go": "ghost_call", "fx": {"suspA": 1, "batt": -3, "flags": {"got_call": 1}}}, {"t": "不接。把手机屏幕朝下放在桌上", "go": "blood_start", "fx": {"wisdom": 1, "flags": {"rejected_call": 1}}}]}, "ghost_call": {"text": ["没有信号杂音，只有急促的呼吸声。一个男人用粤语说——虚弱，像正在流血：", "「你已经见过晏归迟了？」「你不是死了吗？」「看来还是迟了。」", "「不要去苍山。山月盘不在苍山。」「那在哪里？」「就在你住的民宿下面。」", "声音越来越远。「还有一件事。七号房里的六块月钥——有一块是假的。」", "通话中断。屏幕只剩一行字：电量剩余17%。", "你慢慢抬头。六块月钥静静嵌在凹槽里。其中第三块月钥——正在流血。"], "choices": [{"t": "看向铜镜", "go": "blood_start"}], "art": "ringing_phone"}, "blood_start": {"bg": "blood_mirror", "text": ["血从第三块月钥下面渗出来。不是向下流，而是沿着铜镜的裂纹缓缓向上爬，像细小的红色树根在黑色镜面上生长。", "凹槽深处传来极轻的敲击声。叩。叩。叩。像有人被困在墙里，用指节敲打铜镜。", "镜后传出一个女人的声音，很轻，带着哭腔：「小天？真的是你？」", "镜面上的血逐渐聚成一张女人的脸：约三十岁，长发，穿着白色婚纱，裙摆沾满鲜血。她无名指上的戒指，和第三个木盒里的一模一样。", "「今天是我们的婚礼。你为什么又变年轻了？」「我不是你认识的那个杨小天。」「你每一次回来，都这样说。你已经离开我三次了。」"], "choices": [{"t": "「把钥匙拔出来。」听她的", "go": "mirror_trapped", "fx": {"courage": 1}}, {"t": "先反问：「我们第一次见面在什么地方？戒指内侧刻着什么字？」", "go": "mirror_test", "fx": {"wisdom": 1}, "req": {"flag": "planner"}, "note": "数字不会安慰人，但数字可以验证真伪"}, {"t": "「她太想我们拔出来了。」阻止阿月伸手", "go": "mirror_test", "fx": {"wisdom": 1, "flags": {"wise_mirror": 1}}}], "art": "bridal_face"}, "mirror_test": {"bg": "blood_mirror", "text": ["女人没有回答。", "「我读什么专业？」「我们第一次见面在什么地方？」", "她的脸开始扭曲，只会重复：「把钥匙拔出来！拔出来！」", "她张开嘴。嘴角裂得越来越大，一直裂到耳边。发出的不再是女人的声音，而是六个人同时尖叫：「放我出去！」", "一只手突然从你身后伸来，抓住第三块月钥，用力按回凹槽。——晏归迟。", "血液迅速退回裂缝。镜面恢复漆黑。"], "choices": [{"t": "继续", "go": "mirror_aftermath"}], "art": "key_press"}, "mirror_trapped": {"bg": "blood_mirror", "text": ["阿月伸手握住月钥的瞬间，镜中女人停止哭泣，安静地看着你，脸上所有表情一瞬间消失。", "「小天。你忘记我了吗？」——声音突然变成六个男人重叠的低吼。她的嘴角裂到耳边：「放我出去！！」", "晏归迟从身后伸手，把月钥狠狠按回凹槽。血退回裂缝。", "「我叫你们休息。」他说。「我也叫你回答问题。」"], "choices": [{"t": "继续", "go": "mirror_aftermath"}], "art": "key_press"}, "mirror_aftermath": {"text": ["晏归迟用一根红线缠住第三块月钥，打了一个极其复杂的结。", "「刚才是什么？」「门后的东西。」「从来没有那个女人。她戴着第三个杨小天的戒指！」——「镜子见过他的记忆。」", "「它为什么想让我们拔出月钥？」「因为六块月钥不只是开门的东西。」——还是锁。", "「我知道六块钥匙里有一块被换过。只要有人开始怀疑哪一块是假的，就会逐一触碰它们。每碰一次，门便打开一点。」", "你忽然想通：那通电话叫你注意假钥匙，如果晏归迟没有说谎——那不是在警告你。是在引诱你把六块钥匙全部摸一遍。", "「镜子能模仿死人的声音？」「能。」「手机没有信号，它为什么可以打进来？」「因为手机也是镜子。你每天从那块发光的玻璃里看别人，也让别人看见你。它比铜镜更适合开门。」", "你把手机翻过来扣在桌上。阿月用布把它包起来：「现在它看不见你了。」「这有用？」「不知道。」「你不知道也做？」「总比什么都不做好。」"], "choices": [{"t": "接受阿月的安排，把手机包起来", "go": "fire_setup", "fx": {"human": 1, "trustA": 1}}, {"t": "坚持留着手机：「最后一点电，也许能回家」", "go": "fire_setup", "fx": {"wisdom": 1, "flags": {"keep_phone": 1}}}], "art": "red_knot"}, "fire_setup": {"bg": "burning_inn", "text": ["窗外，数十支火箭从黑暗中升起，像一群赤红色的鸟，越过院墙落在沐山驿各处。干燥的木头立刻燃烧。", "「他们不是要抓我们吗？」「现在改主意了。因为刚才那扇门打开的时候，镜子告诉他们东西在这里。」「镜子还可以通知他们？」「不是镜子通知。是镜子里面的人。」", "楼下撞门声。院中刀疤男人高喊：「杨小天！把七号钥匙交出来！我留那个女孩一条命！」", "阿月抬手甩出一枚铁钉，院中一声惨叫，火把落地。「你杀了他？」「射中手而已。」「你怎么知道？」「他叫得很有力。」", "晏归迟把六个木盒塞进布袋：「从后门走。」「后门在哪里？」「没有。」「没有怎么走？」他踢开角落的一块木板，下面是一段向下的楼梯。「所以才不会有人守。」", "燃烧的横梁从屋顶坠下——阿月被撞倒，右腿压在木梁下面。"], "choices": [{"t": "回头", "go": "fire_choice"}], "art": "fire_arrows"}, "fire_choice": {"bg": "burning_inn", "title": "抉择 · 第一次放弃回家的机会", "text": ["火焰隔在两人之间。", "「走！」阿月喊道。", "晏归迟从密道下方抓住你：「来不及了！」「帮我抬开木梁！」「抬不开。」「你还没有试！」", "他望着火焰另一边，脸上没有表情：", "「前六个杨小天都试过。他们都跟我走了。阿月死了六次。这是她第七次被压在同一根木梁下面。」", "「这是已经发生过六次的事。你救不了她。历史不会因为你再试一次就改变。」", "你想起病房里那个在母亲死后才打出十七通电话的自己。", "有些选择，做完以后才能知道对错。有些选择，根本不应该等到结果出来。"], "choices": [{"t": "「那就让它发生第七次。」——冲进火里", "go": "fire_rescue", "fx": {"courage": 2, "human": 2, "flags": {"saved_ayue": 1, "gave_home_1": 1}}, "note": "你的理智会永远质问这个选择。但你还是会跳"}, {"t": "用跆拳道的方式思考：重心、支点、角度", "go": "fire_rescue", "fx": {"courage": 1, "wisdom": 2, "human": 1, "flags": {"saved_ayue": 1, "lever": 1, "gave_home_1": 1}}, "req": {"flag": "blackbelt"}, "note": "练过怎样在力量不如对手时，利用支点和角度"}, {"t": "相信「历史」，跟着晏归迟进入密道", "go": "history_repeats", "fx": {"regret": 2, "flags": {"left_ayue": 1}}, "note": "和前面六个杨小天的选择一模一样"}, {"t": "拒绝所有人：「我不信你。我要自己带她走」", "go": "fire_rescue", "fx": {"courage": 1, "trustA": -1, "flags": {"saved_ayue": 1, "defiant": 1, "gave_home_1": 1}}}], "art": "falling_beam"}, "history_repeats": {"text": ["你转身踏上阶梯。", "身后，火里传来阿月最后的声音——不是惨叫，只是很平静地说了一句你没听清的官话。", "密道尽头，晏归迟停下脚步。他看着你的眼神，像在看一件已经看过六次的东西。", "「你和他们，真的一模一样。」", "就在这时，你胸口的七号铜牌冷得像冰。手机屏幕自己亮了，来电显示：杨小天。", "你接了。那头是阿月的声音，气若游丝：「原来……真的回不来。」"], "choices": [{"t": "冲回去", "end": "E2", "note": "来不及了。历史不会因为你哭就改写"}, {"t": "继续往前走", "end": "E2"}], "art": "descend_ashes"}, "fire_rescue": {"bg": "burning_inn", "text": ["浓烟灌进肺部，眼睛被熏得睁不开。你扑到阿月身旁，抓住燃烧的横梁——木头很烫，皮肤传来剧痛。", "「你回来干什么？」「救你。」「你抬不动！」「你少说一句，我可能会多一点力气。」", "横梁纹丝不动。晏归迟说得对，太重了。你不是武林高手，更没有突然得到神力。", "但你看见旁边有一根断裂的窗柱。你把窗柱插进横梁下面，又在地上垫上一块砖。", "「阿月，等我数到三，用另一条腿蹬地。」「这样不行。」「你有更好的方法？」", "「一。」火焰烧上你的衣袖。「二。」楼下传来军士的喊声。「三！」", "你用整个身体压向窗柱。以砖块为支点，另一端缓缓抬起横梁。只有几寸。已经足够。", "阿月抽出右腿，两人同时滚开。横梁重新坠下，火星四散。", "「能走吗？」「能。」她刚踏出一步，右腿立即一软。「这叫能？」「比死好一点。」"], "choices": [{"t": "扶着她冲进密道", "go": "bronze_door"}], "art": "lever_beam"}, "bronze_door": {"text": ["密道比你想的深得多。至少深入地下十几丈，前面出现一道青铜门。", "门上没有锁，只有一个半月形凹槽。数字是七。", "「这里是什么地方？」「我不知道。」「你也没来过？」「前六次，阿月死后，你都会立刻跟我离开。从来没有人走到这里。」", "阿月靠在墙上：「这不是我家原来的地道。」", "晏归迟摸着铜门：「它刚刚才出现。」「谁造的？」「不是谁造的。」「那它为什么在这里？」", "他回头看你：「因为你改变了选择。时间也改变了路。」", "追兵正在破坏入口。你拿出七号月钥——铜牌烫得几乎无法触碰。", "「把它放进去，就能开门？」「应该可以。」「门后是什么？」「没有人知道。」「也可能是陷阱。」「后面的人不是可能杀我们，是一定会杀。」"], "choices": [{"t": "插入月钥，开门", "go": "toilet_door", "fx": {"courage": 1}}, {"t": "开门前，把阿月拉到身后，自己先进", "go": "toilet_door", "fx": {"courage": 1, "human": 1, "trustA": 1}}, {"t": "犹豫。最后晏归迟替你按了下去", "go": "toilet_door", "fx": {"regret": 1, "flags": {"an_pushed": 1}}}], "art": "bronze_door"}, "toilet_door": {"bg": "washroom_mirror", "title": "第六章 · 没有影子的人", "art": "knife_throat_door", "text": ["门后没有地道，也没有山洞。", "是一间现代洗手间。惨白的瓷砖，布满水渍的镜子，关不紧的水龙头。滴。滴。滴。", "正是你穿越前去过的洗手间。", "手机忽然恢复信号，大量信息同时涌进来：同学群组、母亲的信息、民宿未接来电。屏幕时间终于开始跳动——10:42:58。59。10:43。", "门后就是现代。只要踏出一步，你就可以回家。", "一个熟悉的身影出现在洗手间门口——沐山月柜台后的女孩。「杨先生，你去了哪里？我们找了你好久。」「多久？」「快二十分钟了。」", "现代，只过去了二十分钟。", "你向前走了一步。女孩这才看见你身后的阿月和晏归迟，脸色瞬间惨白，手机掉在地上。", "她只盯着你手里的七号月钥：「你从哪里拿到的？这是你给我的房卡。」——「不可能。七号房在十二年前死过人。从那以后，我们根本没有七号房。」", "「我住的就是七号房。」「你住的是六号。这块钥匙，已经跟那个死人一起下葬了。」", "洗手间的灯突然熄灭。黑暗中，有人从现代这一边抓住你的手腕。一个男人贴近你耳边，用粤语轻声说：", "「不要回头。晏归迟没有影子。」"], "choices": [{"t": "回头看他", "go": "duan_intro", "fx": {"courage": 1}}, {"t": "照做，不回头，把阿月往门内拉", "go": "duan_intro", "fx": {"wisdom": 1, "human": 1, "trustA": 1}}]}, "duan_intro": {"text": ["抓住你的是个六十岁左右的男人：很瘦，民宿深色工作服，头发花白，左手少了一根小指。", "「这里的老板。段云生。我在香港住了三十年。」", "他把你们拉进现代一侧，感应水龙头自动出水——如此普通的声音，此刻听起来竟有一种令人想哭的亲切。", "「把七号钥匙给我。门就要关了。」「关了会怎样？」「你会留在这边。」「那不是正好吗？」「对你也许是。对她不是。」", "灯光下你看清了：阿月的影子越过青铜门，延伸到现代瓷砖上，很长，很清楚。", "晏归迟站在她后面。脚下什么也没有。", "门后的晏归迟忽然开口（也是粤语）：「段云生，你老了。」「你却一点也没变。」「你还在守这间客栈？」「有人需要守门。」「你守不住。」「以前守不住，不代表这一次也守不住。」"], "choices": [{"t": "「十二年前，也有一个杨小天来过？」", "go": "twelve_years", "fx": {"wisdom": 1, "flags": {"ask_12": 1}}}, {"t": "先确认阿月的安全：握紧她的手，把她拉到自己身侧", "go": "twelve_years", "fx": {"human": 1, "trustA": 1}}], "art": "severed_pinky"}, "twelve_years": {"text": ["「有。」段云生终于看你，「六十二岁。就是死在七号房的那个人。」「他死了？」「埋了。院子的梅树下面。」", "你想起现代沐山月院中那棵梅树——黑白照片里它还很矮，现在已经长得很高。原来树下埋着一个人。一个六十二岁的杨小天。", "「我的房卡明明写着七。」——女孩声音发颤：「我给你的房卡上没有数字！」", "你回忆办理入住时的情形。你真的看清楚上面的数字了吗？还是进入十五世纪以后，才第一次注意到那个「七」？", "「它不是我们民宿的房卡。是十二年前跟尸体一起埋下去的东西。」「怎么会跑到我手里？」「因为门选了你。」「谁的门？」", "段云生望向洗手间的镜子。镜面映出所有人——你、段云生、女孩、阿月。唯独没有晏归迟。", "「不是谁的门。门本身就是活的。」"], "choices": [{"t": "「我要回去。现在。」", "go": "second_chance", "fx": {"courage": 1}}, {"t": "先问清楚再行动：「门为什么选我？」", "go": "second_chance", "fx": {"wisdom": 1, "flags": {"why_me": 1}}}], "art": "twelve_graves"}, "second_chance": {"bg": "burning_inn", "title": "抉择 · 第二次放弃回家的机会", "text": ["古代那一边，追兵打破了密道入口。刀疤男人第一个冲下楼梯。", "他看见敞开的青铜门，看见门后的现代，脸上没有惊讶，只有兴奋：「门开了！抓住七号！」", "两名军士扑向阿月。她右腿受伤，动作慢了很多，被侧面踢中，撞在青铜门上，刀落在地上。", "刀疤男人走到她身后，刀架在她颈上：「七号钥匙。交出来。」", "你站在现代。阿月站在古代。只差一步。", "段云生压低声音：「你现在回去，可能再也回不来。」「我知道。」「你母亲还在等你。」「我也知道。」「那你还要回去？」"], "choices": [{"t": "「如果我现在不回去，以后就算回到家，也会一直记得这一刻。」——冲回去", "go": "extinguisher", "fx": {"courage": 2, "human": 2, "flags": {"saved_ayue": 1, "gave_home_2": 1, "extinguisher": 1}}, "note": "你抓起墙上的红色灭火器"}, {"t": "抓住门框，把阿月拽过来，哪怕自己一半留在古代", "go": "extinguisher", "fx": {"courage": 1, "wisdom": 1, "flags": {"saved_ayue": 1, "gave_home_2": 1, "half_pull": 1}}}, {"t": "留下。这是回家的唯一机会", "end": "E3", "fx": {"regret": 2}, "note": "你已经回来过一次了。历史课教过：不要为沉没成本再犯一次错"}], "art": "powder_cloud"}, "extinguisher": {"bg": "burning_inn", "text": ["「阿月！低头！」——她听不懂灭火器是什么，但她听得懂低头。", "你按下压把。大量白色干粉喷出。刀疤男人和军士从没见过这种东西，本能地以为是毒烟，立刻后退。", "阿月趁机一肘击中身后军士的下巴，夺回短刀。", "你跨过青铜门。脚下从瓷砖变回石地。你又回到了十五世纪。", "刀疤男人从白雾里扑出，一刀劈下。你举灭火器阻挡——刀刃砍在金属瓶身上，当的一声，火花四溅，双手发麻，灭火器掉在地上。", "他再次举刀。你没有后退。你踏前一步，右脚横扫——不是踢人，是踢中地上的灭火器。红色铁瓶旋转着撞向他的脚踝，他重心一歪。你转身，肩膀撞进他怀里，两人一起倒地。刀擦过你耳侧，削断几根头发。", "阿月冲到门边，却没有自己过去，回头抓住你的衣领把你拖起来。", "「你们一起过来！」——刀疤男人从地上爬起，毫不犹豫地追向青铜门。", "晏归迟却突然伸手挡在他面前。", "「你不能碰我。」「我知道。」「你也拦不住我。」「我不需要拦很久。」他低头看了看并不存在的手表，「还有七秒。」"], "choices": [{"t": "冲过门", "go": "door_slams"}], "art": "powder_cloud"}, "door_slams": {"bg": "washroom_mirror", "text": ["刀疤男人举刀砍向晏归迟。刀锋从他身体穿过。没有鲜血，没有伤口。他的身体像水中的倒影，短暂扭曲一下，随后恢复。", "你终于明白段云生为什么说他是死人。晏归迟根本没有实体。他不是站在那里——只是「出现在」那里。", "「三秒。」他绕过晏归迟冲向门槛。「一秒。」段云生把七号月钥从凹槽拔出。", "青铜门轰然关闭。刀疤男人的右手刚好越过门槛——门合拢的一瞬间，他的小指被整齐切断。一截手指掉在洗手间地面。", "你看着那截手指。又看向段云生的左手。", "段云生同样没有小指。位置完全相同。他立刻把手藏到身后。已经迟了。", "「你的手指……」「巧合。」「你说谎。」「以后再解释。」", "青铜门消失了。墙上只剩普通的白色瓷砖，仿佛那里从来没有过门。", "晏归迟也不见了。"], "choices": [{"t": "继续", "go": "back_home"}], "art": "severed_pinky"}, "back_home": {"text": ["阿月站在洗手间中央，看着头顶的灯、自动出水的水龙头、墙上的烘手机。她没有表现出恐惧，只是转身摸了摸青铜门消失的位置。", "「回不去了？」「暂时。」她低头看地上那截手指：「那个人还活着？」「在他的年代，应该活着。」", "回民宿的路上，你扶着阿月经过灯火通明的步行街。音乐没有停止，卖花的小女孩还在人群中穿梭。没有人注意到，一个来自1450年的少女正从他们身旁经过。", "阿月看见街上的灯，停下脚步：「这些都是火？」「电灯。」「不会烧起来？」「通常不会。」", "一辆电动车驶过，她立刻按住短刀：「那是什么？」「车。」「没有马。」「未来的车不需要马。」「那它吃什么？」「电。」「电是什么？」", "你想了想：「很难解释。」她看你一眼：「因为你也不知道。」", "你无话可说。"], "choices": [{"t": "教她认字：在起雾的橱窗玻璃上写下「海」", "go": "letter", "fx": {"human": 1, "trustA": 1, "flags": {"taught_sea": 1}}}, {"t": "把外套披在她身上，挡住路人视线", "go": "letter", "fx": {"human": 1}}], "art": "neon_street"}, "letter": {"bg": "ending_buchi", "title": "第七章 · 守门人的真名", "text": ["沐山月。段云生锁上大门，拉上所有窗帘。", "院子中央，梅树静静立在月光下。阿月看见它，脸色突然变了：「这棵树……我父亲死后，我把他埋在这里。」", "段云生站在树下：「十二年前，我也埋过一个人。」", "他蹲下，扒开树根旁的泥土，取出一个防水金属盒：一封信、一张照片、一部旧手机。", "信封上写着：「十八岁的杨小天亲启。」字迹和你一模一样。", "「只有当你第二次放弃回家的机会，才能把信交给你。第一次，是你返回火场救阿月。第二次，是你刚才已经踏进现代，又为了她回到门后。」", "「现在你有资格看了。」"], "choices": [{"t": "拆信", "go": "three_truths"}], "art": "moon_gate_plaque"}, "three_truths": {"bg": "blood_mirror", "art": "letter_moon", "text": ["给十八岁的我：", "「如果你看见这封信，说明阿月还活着。这是好事。也是所有灾难真正开始的地方。」", "记住三件事：", "第一，不要带阿月去苍山。", "第二，第三块月钥不是假的。假的是第一块。", "第三，晏归迟不是没有影子。", "——写到这里，笔迹停顿了一下。后面的字比前面更重，像写信的人曾经犹豫很久：", "晏归迟就是影子。他是山月镜从我身体里剥出来的东西。他拥有我的记忆、声音和后悔。但他不是我。真正的晏归迟，已经在2056年死了。", "信的最后，一行几乎刺破纸面：", "「无论他说什么，都不要让他得到第七块月钥。」"], "choices": [{"t": "第一反应：检查钥匙", "go": "key_gone", "fx": {"flags": {"check_key": 1}}}, {"t": "第一反应：抬头看二楼", "go": "key_gone", "fx": {"courage": 1, "flags": {"looked_up": 1}}}, {"t": "把信折好收进内袋，先问段云生：「照片里是谁」", "go": "key_gone", "fx": {"wisdom": 1, "flags": {"photo_clue": 1}}}]}, "key_gone": {"bg": "yanguichi", "art": "window_key7", "text": ["你慢慢抬起头。", "七号月钥原本被段云生握在手中。现在，不见了。", "「钥匙呢？」段云生低头看自己的手。空的。", "院子二楼忽然传来房门打开的声音。三人同时抬头——一个穿灰色长袍、两鬓斑白的人站在七号房的窗边。", "晏归迟。", "他伸出右手，指间夹着那块半月形铜牌。数字七在月光下闪烁。", "这一次，他的脚下有影子。影子很长，从二楼一直延伸到院子中央。影子的头部，恰好落在阿月父亲、和六十二岁杨小天的坟墓上。", "「信看完了？」「你不是不能进入现代吗？」「以前不能。现在可以了。」「把钥匙还给我。」「当然。只要你上来拿。」"], "choices": [{"t": "「你想要什么？」——保持冷静，先谈", "go": "yuan_name", "fx": {"wisdom": 1}}, {"t": "冲上楼", "go": "yuan_name", "fx": {"courage": 1}, "req": {"stat": {"courage": ">=3"}}}, {"t": "冲上楼", "end": "E1", "req": {"stat": {"courage": "<3"}}, "hint": "你的手在发抖。晏归迟在楼上看着你，像看着第六次、第五次、第四次的你"}]}, "yuan_name": {"bg": "yanguichi", "text": ["「谈一谈。」晏归迟说。", "段云生挡在楼梯前：「不要跟他说话。」「为什么？」晏归迟笑，「怕我说出你的真名？」", "阿月一直看着二楼——不是看晏归迟，而是他的影子。影子从二楼落下，晏归迟明明没有动，影子的右手却在地面上缓缓爬行，五指张开，一点点靠近树下刚挖开的金属盒。", "「影子在动。」阿月说。段云生一脚踩下，黑影迅速缩回。", "「十二年前，我吃过一次亏。」「那次亏，断的是别人的命。」", "「为什么不告诉他们，你是谁？」晏归迟转向你们，改用阿月能听懂的官话：", "「段云生不是他的真名。他姓罗。单名一个铮字。」", "罗铮。这个名字仿佛一把刀。阿月脸上所有血色瞬间消失。"], "choices": [{"t": "挡在段云生面前，对阿月说：「先让他说完」", "go": "luo_truth", "fx": {"wisdom": 1, "human": 1}}, {"t": "什么都不说。看着阿月的眼睛", "go": "luo_truth", "fx": {"courage": 1}}, {"t": "抢先说出你已知的：「他的手和刀疤男人少同一根手指」", "go": "luo_truth", "fx": {"wisdom": 1, "flags": {"finger_clue": 1}}}], "art": "knife_neck"}, "luo_truth": {"bg": "ending_buchi", "art": "knife_neck", "text": ["阿月拔刀。段云生不躲。刀尖停在他咽喉前。", "「是你带人抓走我父亲的。」「是。」「那晚闯进我家的人也是你？」「是。」「我父亲的手，是不是你打断的？」", "他闭上眼睛：「是。」", "「那你为什么不躲？」「因为我等了五百多年。」「等我杀你？」「等你活着站在我面前。」", "段云生说：今晚以后，他还会在景泰元年的大理活十二年。十二年后（2014年），他会再次打开山月门，带来一个六十二岁、重伤的杨小天——因为他答应告诉他，怎样回到阿月父亲被捕以前。", "「你父亲替我打开牢门，叫我带你离开大理。」「我没有来。」「我到的时候，屋子已经烧了。」", "「我找了十二年。」「你从来没有找到？」「因为我没有死。」", "二楼传来晏归迟的声音：「故事很感人。可惜，他漏了一件事——六十二岁的杨小天不是伤重而死。是被段云生杀死。」", "「挖出来。」你说。铲尖碰到木头。不足两米的棺材。", "棺木里没有尸体。只有一套灰色西装、一副眼镜、一只停走的手表——和一块数字「一」的半月形铜牌。"], "choices": [{"t": "拿起一号月钥", "go": "shadow_steals", "fx": {"inv": {"key1": 1}, "flags": {"took_key1": 1}}}, {"t": "先问段云生：「空棺材是什么意思？」", "go": "shadow_steals", "fx": {"wisdom": 1}}, {"t": "不碰。让它留在原来的位置", "go": "shadow_steals", "fx": {"wisdom": 2, "flags": {"suspicious_key1": 1}}, "req": {"stat": {"wisdom": ">=3"}}, "note": "信上说过：假的是第一块。假的东西，为什么在尸体旁边？"}]}, "shadow_steals": {"bg": "yanguichi", "text": ["段云生伸手：「给我。」", "地上的影子比他更快。一道黑影从梅树枝下窜出，缠住你的手腕，月钥脱手飞起——晏归迟仍然站在二楼，影子却已经把第一块月钥送到他手中。", "一号。七号。两块月钥同时发出微光。晏归迟的身体变得更加清晰。他的影子反而越来越淡，最后完全消失。", "「谢谢。」", "段云生冲向楼梯，楼梯口的木门自动关闭。整座民宿开始震动，墙上装饰画全部倾斜，玻璃杯摔得粉碎。", "「一号钥匙不是假的？」你仰头喊。", "晏归迟道：「你信里写的是——镜框上的第一块是假的。这一块才是真的。一号代表第一次来到这里的杨小天。七号代表你。一个是开始，一个是结束。」", "他把两块月钥合在一起。两个半月形成一个完整的圆。铜牌中央出现一条极细的裂缝——裂缝里不是金属，是一只眼睛。", "眼睛缓缓睁开。瞳孔中映出苍山的雪。"], "choices": [{"t": "继续", "go": "all_mirrors"}], "art": "shadow_hand"}, "all_mirrors": {"bg": "shanmoon_core", "text": ["民宿所有镜子同时破裂。每一块碎片里，都出现不同的景象：", "香港街道。古代战场。医院病房。大学礼堂。一间燃烧的跆拳道馆。", "还有一座隐藏在苍山深处的石室。石室中央，放着一个巨大的青铜圆盘。", "「山月盘。」段云生说。", "晏归迟把圆形月钥按在二楼房门上，木门中央出现水波般的纹路。", "「不要让他开门！」段云生大喊。", "「为什么？」「山月盘不是用来穿越时间！」「那是做什么的？」「删除时间！」", "房门打开。门后不是七号房，是一条通往苍山内部的石阶，寒气从门中涌出。", "「你不是一直想知道，谁杀死前面六个你吗？跟我来。尸体都在里面。」", "他说完，走进门后。"], "choices": [{"t": "跟进去", "go": "cangshan_gate", "fx": {"courage": 1}, "note": "「他说的可能是陷阱。」「当然是陷阱。」「那你还想进去？」「因为其他人也在说谎。」"}, {"t": "先带阿月和段云生撤出去商量", "end": "E4", "hint": "门会一直在那里。晏归迟等的就是这个"}, {"t": "带走灭火器", "go": "cangshan_gate", "fx": {"wisdom": 1, "human": 1, "flags": {"extinguisher": 1}}, "note": "目前为止，它比未来知识有用"}], "art": "mirror_shards"}, "cangshan_gate": {"text": ["段云生拦住你：「信上写得很清楚，不要带阿月去苍山。」", "阿月问：「为什么不能带我去？」段云生答不上来。", "「那封信也可能是假的。」阿月说。「如果我父亲真的制造过山月盘，那里就可能有他留下的东西。」她走进了门后。", "段云生在你身后低声说：「进去以后，不要相信看见的任何尸体。山月盘不能让死人复活——但它可以让活人以为自己已经死了。」", "「你到底还隐瞒了多少？」「多到现在说不完。」", "他看了一眼院子：柜台女孩还躲在柱子后面。外面是2026年的大理古城。他在这里生活了十二年，学会了手机、汽车、电灯和网络，以为自己永远不会再回到那个野蛮、肮脏而危险的时代。", "最后，他弯腰捡起阿月掉下的短刀：「走。」"], "choices": [{"t": "三人一起进入门后", "go": "cave", "fx": {"courage": 1}}], "art": "stone_stair"}, "cave": {"bg": "shanmoon_core", "title": "第八章 · 第七把钥匙", "text": ["石阶尽头是一座人工修建的平台，平台中央放着直径超过两丈的青铜圆盘。", "圆盘四周刻满星辰，中心却不是天空——是一片绝对的黑暗。", "晏归迟站在圆盘前。他身旁整齐地躺着六具尸体：毕业袍、黑带、结婚戒指、蜡笔画、2047年的报纸、染血的黑色运动外套。", "六具尸体，同时睁开眼睛。十二只眼睛，一起望向你。", "最年长的那个慢慢坐起——六十二岁，灰色西装，正是空棺材里那套衣服。他胸口没有心脏，只有一个半月形的空洞，边缘刻着数字「一」。", "「他拿走的不是钥匙。是我的心。」", "阿月看见平台另一端坐着一个人：头发凌乱，双手不自然地弯曲。短刀从她手中掉落。", "「爹？」", "男人抬头，眼中没有喜悦，只有恐惧：「不要过来！阿月，快走！杨小天不是第七个人——他根本不是人。他就是山月盘制造出来的第七把钥匙！」"], "choices": [{"t": "「我会流血。钥匙不会流血。」", "go": "not_human", "fx": {"courage": 1}}, {"t": "「那我原来的身体在哪里？」", "go": "not_human", "fx": {"wisdom": 1, "flags": {"clone_doubt": 1}}}, {"t": "看向阿月：「你父亲说的，你信吗？」", "go": "not_human", "fx": {"human": 1, "trustA": 1}}], "art": "six_lie"}, "not_human": {"text": ["阿月父亲摇头：「山月盘制造的，不是你的身体。是你的现在。」", "「你当然是人。你有父母，有童年，有真正经历过的十八年。但站在这里的你，并不是原来那个杨小天。」", "「原来的我在哪里？」他指向青铜圆盘中央那片绝对的黑暗：", "「还在十点四十二分。还站在洗手间的镜子前面。你只是他在那一刻产生的另一个选择。」", "「原来的你看见镜子里的土墙以后，立刻离开了洗手间。他回到民宿，第二天继续旅行，几个星期后进入大学。他从来没有穿越，也没有见过阿月。」", "「我是他在镜子前多停留了一秒的结果。」", "「所以我只是一个副本？」", "「不。」回答你的不是阿月父亲，是六十二岁的杨小天。", "「不要相信他那种说法。没有哪一条人生是副本。你一旦作出了不同选择，从那一刻开始，就是真的。你会痛，会怕，也会因为另一个人回头——这已经足够证明你是人。」"], "choices": [{"t": "接受这个答案，继续面对晏归迟", "go": "offer", "fx": {"human": 1, "flags": {"accept_self": 1}}}, {"t": "无法释怀：「如果我真的是假的，这一切有什么意义？」", "go": "offer", "fx": {"regret": 1}}, {"t": "反问六十二岁的自己：「那你呢？你也是副本吗？」", "go": "offer", "fx": {"wisdom": 1, "flags": {"asked_old": 1}}}], "art": "chest_hollow"}, "offer": {"bg": "shanmoon_core", "title": "完美的提议", "art": "void_gaze", "text": ["晏归迟将圆形月钥靠近青铜盘，山月盘上的星辰逐一点亮，仿佛整座苍山正在转动。", "「你想做什么？」「把你没有活过的人生还给你。」", "他逐一介绍六个杨小天：第一个留校研究时间物理，最早发现山月盘；第二个成为跆拳道教练，没赚很多钱，却带出几个很好的学生；第三个结婚，又离婚——「镜子给你看的女人，根本不是我太太。真正的她还活着。只是恨我。」第四个有女儿，很爱她，也很少回家；第五个成为企业家，「死得最像新闻」；第六个经营道馆失败，想回到十八岁——「也所以你杀了我。你没有用刀。但你知道那些人在等我。你还是把门打开了。」", "「如果你得到他们全部的记忆，就不会再走错路。你会知道哪一个专业最适合自己，哪一个朋友将来会背叛你，哪一个人值得爱，哪一次投资会令你富有，哪一通电话必须接，哪一顿饭不能错过。你甚至会知道，母亲在哪一天离开。」", "「你不用在大学、跆拳道、事业和家庭之间选择。你会拥有他们六个人最好的部分，避开所有最坏的结局。」", "你没有立刻拒绝。因为这个提议太诱人——不是财富，不是成功，而是不再后悔。", "那不是重新生活。是带着答案参加考试。", "而你最擅长的，正是有答案的考试。"], "choices": [{"t": "「代价是什么？」", "go": "price", "fx": {"wisdom": 1}, "note": "因为你不肯主动说"}, {"t": "「好。我接受。」", "end": "E6"}, {"t": "「不需要。我的人生我自己走错。」", "go": "price", "fx": {"courage": 1, "human": 1}}]}, "price": {"bg": "shanmoon_core", "text": ["晏归迟的笑容消失了一点：「代价只是删除一些不再需要的时间。六条失败的时间线会消失。他们本来就已经死了。」", "「阿月呢？」山洞忽然安静下来。", "「她不应该活到现在。如果我接受，她会回到已经发生过六次的结局。」——就是死。", "你摇头。「你只认识她几天。」「够了。」", "「你愿意为了一个认识几天的人，放弃一生不会犯错的机会？」", "「我不知道她值不值得。我只知道，如果必须先让她死，那种人生一定不完美。」", "「你以为前六个没有说过类似的话？他们最后还是选择了自己。」", "「我不是他们。」晏归迟望着你，「第七个也不会有什么不同。」", "「那你为什么一直想说服我？——因为门必须由我自己打开。你不能强迫我，否则你早就动手了。」", "他脸上的笑容，完全消失了。"], "choices": [{"t": "继续", "go": "flip"}], "art": "void_gaze"}, "flip": {"text": ["阿月父亲忽然大喊：「阿月，杀了他！」「杀谁？」「杨小天。只要第七把钥匙死去，山月盘就无法完成。它会把前面六条时间全部放回原处。你也会回到今晚以前。他呢？他从来没有存在过。」", "阿月看着你，手中的短刀慢慢抬起。", "「你相信你父亲吗？」「相信。」「那就动手。」", "刀锋抵住你的胸口。「你不怕？」「怕。」「为什么不逃？」「因为我刚才还在想，如果我是假的，可能死了也没有什么。」", "「现在呢？」「现在觉得，就算是假的，也不太想死。」", "她转身将短刀掷出——不是射向你，而是射向山月盘！刀尖击中一号月钥，晏归迟手掌一震，圆形月钥松开半寸。", "六十二岁的杨小天突然扑出，双手抓住晏归迟。另外五个杨小天也同时站起。", "「现在！」老人喊道。段云生举起阿月父亲掉落的铁锤，重重砸在青铜盘上。第一次，没有变化。第二次，圆盘出现裂缝。第三次，整个山洞剧烈震动。", "晏归迟终于露出恐惧。他身体下面的影子突然分裂，六道黑影钻进六个杨小天脚下——他们的动作同时停住。"], "choices": [{"t": "看着那六个人松开手", "go": "hall_enter"}], "art": "thrown_knife"}, "hall_enter": {"bg": "exam_hall", "text": ["「你们忘了自己为什么回来？」晏归迟低声道。", "穿毕业袍的杨小天首先松手——他看见大学礼堂，母亲坐在台下鼓掌。系黑带的看见学生回到道馆。第三个看见妻子没有离开。第四个看见女儿扑进怀里。第五个看见自己没有登上失事的飞机。第六个看见道馆重新开门。", "「只要门打开，」晏归迟说，「你们全都可以重来。」", "每个人都看见自己最想改变的过去。没有人再阻止他。", "你终于明白：晏归迟不是某一个杨小天的影子。他是所有杨小天的后悔。只要一个人仍然希望「如果当初」，晏归迟便不会消失。", "「你到底是谁？」「我是你每一次在深夜问自己的那句话。」「哪一句？」「如果我当时选择另一条路，会不会更好？」", "圆形月钥完全嵌入青铜盘。你胸口传来剧痛——皮肤下面浮现半月形光芒。你终于看见了自己的钥匙孔：不在铜牌上，在心脏的位置。", "黑暗包围你的双脚。无数声音问你：你后悔吗？——然后你睁开眼睛。", "面前是一张课桌。"], "choices": [{"t": "……", "go": "exam_hall"}], "art": "six_eyes"}, "exam_hall": {"bg": "exam_hall", "title": "第九章 · 最后一科", "art": "empty_chairs", "text": ["桌上放着准考证、透明文具袋和一份尚未打开的试卷。四周坐满穿校服的学生。墙上的时钟：上午八点二十九分。", "「考试马上开始，不要睡觉。」监考老师站在你身边。", "你抬头看黑板——上面写着考试日期。正是你DSE最后一科考试的那一天，也是你中学生涯的最后一天。", "八点三十分，铃声响起。所有考生同时翻开试卷。试卷上只有一道题：", "「假如人生可以重来，你会选择同一条路吗？」", "下面有七个选项：A 进入最理想的大学。B 继续跆拳道。C 选择爱情和家庭。D 成为父亲。E 追求财富和事业。F 回到失败以前。G 接受以上六条人生的全部记忆。", "没有「都不选择」。也没有「自己决定」。", "你望向窗外：走廊尽头站着穿深蓝色衣服的少女。她隔着玻璃看你，嘴唇无声地说了四个字——", "「不要交卷。」", "监考老师走上讲台，抬起头。那张脸，属于晏归迟。", "「考试开始。」"], "choices": [{"t": "在题目旁边写：「为什么只有这七个答案？」", "go": "exam_a", "fx": {"wisdom": 1}}, {"t": "举手交卷，选择其中一个选项", "end": "E5", "note": "穿毕业袍的自己，就是这样消失的"}, {"t": "盯着窗外，看阿月接下来做什么", "go": "exam_a", "fx": {"human": 1, "trustA": 1}}]}, "exam_a": {"bg": "exam_hall", "text": ["字刚写完，纸上的墨迹立刻消失。仿佛试卷不允许你提出问题。", "前面的考生举起手：「老师，我选A。」——那是穿毕业袍的杨小天。晏归迟收走答题册，他松了一口气，随后身体从脚开始消失。鞋、长袍、双手，最后是脸。几秒后，座位上只剩一张空椅子。没有人抬头。", "第二个。第三个。第四个。第五个。六种人生依次交卷，六个杨小天依次消失。礼堂越来越空。", "最后只剩你。", "「他们都已经选择。现在轮到你。」", "「距离考试结束还有多久？」「由你决定。」「如果我不作答？」「你会永远留在这里。」", "「阿月呢？」「她不属于这场考试。」「那她为什么会在外面？」「因为你希望她在。你害怕独自作决定，所以山月盘替你制造了一个陪伴。」", "「她是假的？」", "「这里所有东西都是假的。」「包括你？」「我从来没有说过自己是真的。」"], "choices": [{"t": "看阿月下一步", "go": "exam_blood", "fx": {"human": 1}}, {"t": "「证明给我看。她是假的，为什么你不敢看她现在会做什么？」", "go": "exam_blood", "fx": {"courage": 1, "wisdom": 1, "suspA": -1}}], "art": "blood_writing"}, "exam_blood": {"bg": "exam_hall", "text": ["走廊上的阿月突然抬手，用手指在玻璃上写字。玻璃上没有雾气。", "她便咬破指尖，用血来写。一笔。一画。写得很慢。字是反的——因为她从玻璃另一边写。", "你看了很久，才认出来。四个字：", "「撕掉名字。」", "名字？试卷上没有姓名。DSE不会要求考生写姓名，以免阅卷泄露身份。真正代表考生的，是条形码标签。", "桌上总共有七张条形码。前六张已经被撕走。只剩最后一张：YEUNG, SIU TIN，杨小天。下方一个很小的数字：7。", "原来这才是第七把钥匙。不是黄铜牌，不是你的身体——是你的身份。只要你承认自己属于其中一个答案，山月盘便能把那条人生贴在你身上。"], "choices": [{"t": "「她不是假的。因为你不知道她在写什么。你一直看我，没有阻止她。」", "go": "tear", "fx": {"wisdom": 1, "human": 1, "flags": {"ayue_real": 1}}}, {"t": "不辩论。直接撕下条形码", "go": "tear", "fx": {"courage": 1}}], "art": "blood_writing"}, "tear": {"bg": "exam_hall", "title": "交白卷", "text": ["你捏住最后一张条形码。", "「你可以制造我记忆里的学校，制造试卷，制造监考老师。但阿月不是我的记忆。我认识她只有几天，你还来不及完全知道她是什么人——所以你不能完整地复制她。」", "晏归迟脸上的笑容完全消失。", "你撕下条形码。「贴上去！」他第一次提高声音。", "「不要命令考生怎样作答。」你把条形码撕成两半，礼堂震动。再撕一次，两半变四片，墙壁出现裂缝。", "「你以为撕掉名字，就可以没有后果？无效的考试也是零分。」「那就零分。」「你会失去大学资格。」「真正的DSE我已经考完。这份是假的。」", "他从讲台后走出来：「你很努力。六年。每天补习。复习到深夜。放弃跆拳道，放弃和同学相处。你真的愿意让所有努力变成零分？你的家人也为你付出。老师对你有期待。父母以你为荣。如果你现在离开，怎么对得起他们？」", "这些话你听过很多次，也相信过很多年。努力不是假的，家人的牺牲也不是假的。正因为这些都是真的，放弃才显得像一种罪。"], "choices": [{"t": "「我没有否定以前的努力。我只是不接受你替我出的题目。」", "go": "alarm", "fx": {"wisdom": 1, "human": 1, "flags": {"zero_paper": 1}}}, {"t": "手停在半空。动摇", "end": "E5", "hint": "他说得对。你确实对不起很多人"}, {"t": "「结果不好，不会令做过的努力消失。结果很好，也不能把错过的时间还给我。」", "go": "alarm", "fx": {"courage": 1, "human": 2, "flags": {"zero_paper": 1}}}], "art": "barcode"}, "alarm": {"bg": "exam_hall", "text": ["你站起来，推开椅子，走向礼堂出口。", "晏归迟挡在门前：「考试开始三十分钟内，考生不得离场。这是规定。」「我知道。」「你一向很守规定。」「以前是。现在打算作弊？」「不。」", "你抬起右脚——「打算交白卷。」", "一脚踢中礼堂的火警警报器。玻璃破裂，警铃大作，红色灯光闪烁，所有出口同时自动打开。", "「发生火警，规定允许离场。」你说。", "他看着破裂的警报器：「你什么时候变得这么会找漏洞？」「香港学生最擅长考试技巧。」"], "choices": [{"t": "冲出礼堂", "go": "washroom2"}], "art": "fire_alarm"}, "washroom2": {"bg": "washroom_mirror", "text": ["阿月在走廊等你。「你怎么进来的？」「不知道。我只记得你被黑暗拉走，然后我看见一道门。门上写着你的名字。」", "身后的警铃逐渐变成山月盘转动的声音。走廊长得不合理，两旁全是教室——每一扇门后，都坐着一个不同年龄的杨小天：有的在考试，有的在工作，有的陪孩子做功课，有的独自坐在医院，有的已经死去。", "走廊尽头是一间洗手间。水龙头仍然关不紧。滴。滴。滴。", "「又是洗手间？」「所有门好像都喜欢开在洗手间。」「为什么？」「可能时间也需要一个不被人看见的地方。」", "镜子里不是你们的倒影，是苍山石室：段云生正在用铁锤砸击山月盘，阿月父亲倒在地上，晏归迟的影子覆盖整个山洞。", "「出口是镜子。」你伸手触碰镜面。坚硬，冰冷，不能穿过。", "晏归迟的声音从背后传来：「打碎镜子，你们会永远困在这里。」", "他已经不再穿灰色长袍，身上是监考老师的黑色西装。手中拿着一张完整的条形码——正是刚才被你撕碎的第七张。", "「东西撕碎以后，可以重新拼好。时间也是。」"], "choices": [{"t": "「刀在这里没有用。」——阿月扔掉短刀，一拳打在他脸上", "go": "mirror_fight", "fx": {"courage": 1, "trustA": 1}}, {"t": "抓起垃圾桶撞向他，为阿月创造撞碎镜子的机会", "go": "mirror_fight", "fx": {"courage": 1, "human": 1}}], "art": "mirror_crack"}, "mirror_fight": {"bg": "exam_hall", "text": ["阿月将刀扔掉，一拳打在他脸上。鼻血流下。「拳头有用。」", "三人扭打在一起。数百名无脸考生从教室涌出：「请考生返回座位。」——同时扑来。", "你举起金属垃圾桶砸向镜面：第一下没有破；第二下，裂纹后面的段云生抬起头，他似乎看见了你。", "他从另一边举起铁锤，砸向同一个位置。两边同时用力。第三下——镜子轰然破裂，碎片悬浮半空。", "晏归迟从后面抓住阿月，把条形码按向她后背！「她不是考生！」「名字只是一张标签，」他说，「贴在谁身上，谁就是第七个。」", "你忽然松开阿月，转而抓住晏归迟的手腕——不抢条形码，而是借着他向前的力量，转身，扭腰，一个最普通的过肩动作。他失去平衡。两人身体交错的一瞬间，你抓住条形码，反手按在他的胸口。", "姓名：杨小天。编号：7。", "整个考试世界安静下来。所有无脸考生同时停步。广播响起：「七号考生已经确认。答题开始。」", "「你做了什么？」「替你报名。」「撕掉它！」——你抓紧他的手腕：「不好意思。考试期间不能撕毁条形码。」", "黑暗从镜子另一边伸出，无数只手抓住晏归迟，把三个纠缠在一起的人一起拖向爆开的镜面。", "世界消失了。"], "choices": [{"t": "坠入黑暗", "go": "hospital2_enter"}], "art": "mirror_crack"}, "hospital2_enter": {"bg": "hospital_2056", "title": "第十章 · 没有倒影的人", "art": "hospital_2056", "text": ["你在无数时间中不断下坠。你看见自己出生，第一次穿上跆拳道服，母亲在小学门口等你，中学毕业，尚未发生的大学生活。", "最后，你再次看见那间医院。2056年，晚上十点四十二分。", "窗外是香港。维多利亚港的海水比记忆中高了许多，低处街道被水淹没，高楼之间架起空中通道。天空没有星星，只有成群的无人机。", "阿月倒在你身旁，没有反应。还有一个人站在病床前——晏归迟。", "他胸前的条形码不见了。灰白的头发变成黑色，皱纹全部消失。他正在变年轻：六十二、五十、三十七、二十三——最后停在十八岁。", "他转过身。那张脸和你完全相同。", "「谢谢你替我贴上条形码。我一直缺少一个名字。现在，我终于可以做人了。」"], "choices": [{"t": "一拳打过去——拳头从他脸上穿过", "go": "shadow_state", "fx": {"courage": 1}}, {"t": "「你的名字，是你自己不要的。」", "go": "shadow_state", "fx": {"wisdom": 1}}]}, "shadow_state": {"text": ["病房玻璃里只有一个倒影——他的。你没有影子，也没有倒影。手指伸向玻璃，像伸进一片没有温度的水。", "「谁贴上标签，谁便得到那条人生。你把自己的名字给了我。现在，我是杨小天。」", "「你没有我的身体。」「山月盘不需要身体，只需要别人相信我是谁。」", "门边的身份识别器亮起蓝光，扫描他的眼睛：身份确认：杨小天。", "「这个世界已经相信我是你。」「我妈妈不会。」", "他的脚步停了一下。「她已经死了。死人不能证明任何事。」", "他按下一个按钮。病房墙壁从中间分开——墙后是一座巨大的实验室：数十个透明舱体，每个都躺着一个杨小天，不同年龄，甚至有女性与只有部分五官像你的后代。实验室中央悬浮着一块吸光的黑色石头，下方刻着三个字：", "山月核。", "「1448年，它坠落苍山。阿月的父亲发现它可以照见没有发生的事，以为是神迹。2051年，我重新找到这块石头。它不是预知未来——它只是保存所有被放弃的时间。」「你制造了山月盘？」「不。我只是教会它怎样使用人。」"], "choices": [{"t": "继续", "go": "mom_wakes"}], "art": "pod_lab"}, "mom_wakes": {"bg": "hospital_2056", "text": ["病床上的女人忽然咳嗽了一声。监护仪仍然没有心跳，她却缓缓睁开眼睛。", "晏归迟握住她的手：「妈，我在这里。」「合约呢？」「我不签了。以后也不走了。我会陪着你。」", "女人轻轻笑了：「你小时候说谎，也是这个声音。」「我没有说谎。」「你每次说『以后』，都在说谎。以后读完这本书，以后考完试，以后工作没那么忙，以后赚够钱，以后有时间。小天，你有过多少个『以后』？」", "「这次是真的。我已经回到十八岁。所有事情都可以重新开始。」「傻孩子。人怎么可能回到十八岁？」", "你忽然明白：眼前的女人不是活人。她只是山月核保留的一段时间——晏归迟把母亲临终前的十八分钟困在这里，不断重播。每一次他都赶回来，每一次都试图说服她自己可以改变。每一次，时间都停在十点四十二分。", "因为他不肯让十点四十三分到来。", "「她已经原谅你了。」你说。", "「住口。」「她从来没有怪你。正因为她没有怪你，你才更痛苦。你不是想救她——你只是想回到过去，变成一个没有做错事的人。」"], "choices": [{"t": "对母亲说：「妈，我返咗嚟食饭。」", "go": "mom_touch", "fx": {"human": 2, "flags": {"told_mom": 1}}}, {"t": "继续质问晏归迟", "go": "mom_touch", "fx": {"courage": 1}}], "art": "mother_eyes"}, "mom_touch": {"bg": "hospital_2056", "text": ["女人缓缓转动眼睛，望向没有倒影的你。「那里还有一个人。」", "她伸出手。手掌穿过金属护栏——像穿过一层水。她的手也变成了半透明。", "原来她和杨小天一样，都是被山月核保留下来的影子。", "她碰到你的脸。这一次，没有穿过去。", "「小天，你才刚刚回来。」「你为什么哭？」「我不知道。」「考试考得不好？」「成绩还没有出来。」「那就等出来再算。」「如果不好呢？」「不好便不好。」", "「你不是一直希望我进最好的大学？」「希望和一定要，是两回事。我希望你过得好。不是希望你每件事都做到最好。」", "她看向晏归迟：「你也叫杨小天？」「我就是杨小天。」「不是。」「为什么不是？」「我的儿子不会那样看我。」「怎样？」「像看一道做错了的题。」", "女人的手仍放在你的脸上：「你已经回来。那就够了。」", "她闭上眼睛。监护仪上的时间终于改变——10:42:59。秒数跳动。十点四十三分。", "长鸣停止，屏幕熄灭。病床上的女人逐渐变得透明。你想抓住她，手指只碰到一点温暖的空气。", "她终于离开了那被重复无数次的十八分钟。"], "choices": [{"t": "……", "go": "name_reveal"}], "art": "mother_eyes"}, "name_reveal": {"bg": "hospital_2056", "text": ["晏归迟站在原地，脸上的愤怒消失了，只剩一个失去母亲的孩子才会有的茫然。", "「为什么？我花了这么多年，我打开六条时间，我回来六次。为什么她还是要走？」", "你没有回答。因为没有答案。有些人离开，不是由于谁做错了，只是时间到了。", "阿月醒了。她看着两张杨小天的脸——如今只剩一张拥有身体。", "「我救你离开火场时，你对我说过什么？」「你说过很多话。」「说一句。」", "他答不上来。她抓起输液架：「你不是他。我有他的全部记忆。」「但他回来救我的时候，那件事以前没有发生过。那是第七次才有的记忆。」", "她环顾病房，看不见你。但她注意到地面：他的脚下有影子，旁边还有另一道很淡的影子——没有身体。", "她看着那道影子：「你在那里？」你走过去。「是。」她听不见。影子却点了一下头。", "她忽然笑了：「找到你了。」"], "choices": [{"t": "继续", "go": "cut_name"}], "art": "faint_shadow"}, "cut_name": {"bg": "hospital_2056", "title": "把名字割下来", "text": ["晏归迟扑向阿月。他拥有六个杨小天的经验，包括七年跆拳道训练。他夺走输液架，一脚把她踢倒。", "「你选择一个影子？」「他至少回头救过我。」「我也可以。」「你不会。因为你总想先知道值不值得。」", "他眼中闪过杀意。地上的影子突然缠住他的脚——你不能碰人，却可以碰影子。", "阿月冲向控制台。你指向晏归迟胸口：条形码虽然消失了，皮肤下面却留着一道黑色印记。", "她抓起手术刀。他抬腿踢来——前踢是假的，真正的攻击来自随后转动的左脚。你立刻抓住他右脚的影子，向相反方向拉。身体慢了半拍。半拍已经足够。", "她扑进他怀里，手术刀划过胸口。黑色条形码被割开。", "他的影子突然膨胀，把你的影子拖进去。两个影子开始重叠，六条人生的记忆同时压进你的意识：母亲的葬礼、破产的道馆、失败的婚姻、女儿离开家时的背影、飞机坠落前最后一道火光。", "「说你的名字！」阿月大喊。", "一个名字并不是因为印在纸上，才属于某个人。是因为有人这样叫。母亲这样叫。朋友这样叫。教练这样叫。现在，阿月也这样叫。"], "choices": [{"t": "「杨小天。」", "go": "delete_starts", "fx": {"courage": 1, "human": 1, "flags": {"named": 1}}, "note": "实验室所有灯光同时熄灭，山月核爆发出刺眼白光"}, {"t": "喊出阿月的名字", "go": "delete_starts", "fx": {"human": 2, "trustA": 1, "flags": {"named": 1, "said_ayue": 1}}, "req": {"stat": {"trustA": ">=4"}}, "hint": "你把名字还给了唯一记得第七次的人"}], "art": "scalpel"}, "delete_starts": {"bg": "hospital_2056", "text": ["你从晏归迟的影子里被拉出来，跌在地上。玻璃墙上重新出现你的倒影。", "他则迅速衰老，最后变回两鬓斑白。胸口流血，却没有倒下。", "「你赢不了。山月核已经记住你的名字。只要你还会后悔，我就不会死。」", "警报响起，机械女声不断重复：", "「时间结构失稳。删除程序即将启动。剩余时间：十八分钟。」", "窗外的香港开始消失。不是爆炸，而是一块一块被黑暗抹去：先是海水，然后是建筑，最后是天空。", "「删除程序是什么？」「山月核正在删除所有产生矛盾的时间。包括1450年、2026年——还有这里。」", "「怎样停止？」「回到山月盘第一次打开的时候。景泰元年。」", "黑石表面出现一道门，门后是正在崩塌的苍山石室。晏归迟迈进门内：「你们想救所有人，便只有十八分钟。」", "阿月要追，你拉住她：「他故意引我们回去。那里一定还有陷阱。」「那你去不去？」「去。因为你父亲还在那里。」", "她看你一眼：「你现在学会不问值不值得了？」「不是。有些问题，边走边想。」"], "choices": [{"t": "冲进山月核", "go": "cave_final"}], "art": "city_erase"}, "cave_final": {"bg": "shanmoon_core", "title": "第十一章 · 第八个答案", "art": "core_rise", "text": ["你们重新跌回苍山石室。山洞正在坍塌，青铜圆盘裂成两半。段云生被压在岩石下，阿月父亲胸口插着一截青铜碎片。六个杨小天重新变成尸体。", "「怎样停止删除？」「毁掉山月核。你看见的黑石只是未来的它。真正的山月核一直埋在这里。」", "地面裂开，心脏大小的黑色石头从苍山深处缓缓升起。它没有反光，却发出和心跳一样的声音。一下。一下。", "「要毁掉它，必须把七把钥匙同时放进去。另外五把，在他们心里。」", "「取出来，他们会怎样？」「六条时间会彻底消失。」「那我呢？」", "他没有回答。你已经知道答案：七把钥匙，七条时间。全部投入，所有杨小天都会消失——包括十八岁的你。", "「不行。」阿月扶住你，「还有别的方法。」「没有时间了。」", "冰冷的机械声从五百多年后传来：「剩余时间：十七分钟。」", "晏归迟站在黑石旁，微笑着：「救自己。还是救三条时间里所有认识和不认识的人。」", "「这一次，没有第三个答案。」"], "choices": [{"t": "面对六具尸体", "go": "seven_questions"}]}, "seven_questions": {"bg": "shanmoon_core", "title": "七问", "text": ["六具尸体的胸口都发出微弱光芒：圆形、弯曲的腰带、结婚戒指下、蜡笔画中、压在报纸日期上、被鲜血覆盖。", "六把月钥。六段没有活完的人生。六个曾经希望重来的杨小天。", "「把钥匙取出来，他们一定会消失？」阿月父亲点头：「山月盘用后悔固定时间。钥匙一旦离开，他们便没有东西留在这里。」", "——留在这里？", "「不是从世界上消失？」你抓住这四个字。「有什么分别？」「分别很大。」", "你走到他们面前。现在，由你问他们问题。"], "choices": [{"t": "一个一个地问", "go": "q_coach"}], "art": "six_glow"}, "q_coach": {"text": ["六十二岁的杨小天先开口：「你原本生活的时间，还存在吗？」「不知道。」「你怎样来到这里？」「想重来。然后我看见一扇门，门后有人问我，愿不愿意放弃已经活过的人生，回到十八岁。」", "「你答应了？」「答应了。」", "「所以不是钥匙把你困住，是你一直不肯回去。」", "然后你走到系黑带的自己面前——那个放弃一切重新练习、成为教练、道馆倒闭、十指变形的自己。", "「你讨厌那条人生？」「没有。」「那为什么要重来？」「我觉得自己失败。」「谁说的？」「所有人。」「你自己呢？」", "他把黑带递还给他：「有没有学生因为你改变？」「有。」「那条人生只有失败？」他握住黑带，过了很久，摇头。", "「后悔吗？」「当然后悔。但我想回去的，不是十八岁。是道馆关门的前一天。我还欠几个孩子最后一堂课。」"], "choices": [{"t": "让他自己取出第二把月钥", "go": "q_rest", "fx": {"human": 1}}, {"t": "替他问出他不敢问的问题：「教练当年是不是说过，暂停的东西不会自己重新开始？」", "go": "q_rest", "fx": {"wisdom": 1, "human": 1, "flags": {"coach_line": 1}}}], "art": "coach_black"}, "q_rest": {"text": ["月钥没有飞向晏归迟，而是落在教练自己掌中。「但人可以。」说完，他消失了——不是死亡，更像从一扇看不见的门回到自己的人生。黑带落在地上，上面已经没有名字。", "第三个人转动无名指上的戒指：「她恨我。」「你还爱她？」「爱。」「所以想回到结婚以前？」「不。我想回到第一次说『以后再谈』以前。如果回不去，那就向她道歉。她不接受？那是她的选择。」——「结束的关系，不等于从来不应该开始。」", "第四个人抚平蜡笔画：「我想回去陪她。不是回到十八岁，是回到她还肯等我回家的时候。如果已经太迟，那就承认太迟。总比抢走另一个十八岁孩子的人生好。」", "第五个人把报纸撕成两半：「我成功过。我以前总觉得，承认喜欢金钱和成功是一件很可耻的事，所以每次失去家人，我都把责任推给事业。其实不是事业逼我，是我自己每次都选择不回去。成功不是罪。以成功为借口，才是。」", "只剩二十三岁的、胸口还在流血的自己。", "「如果回去，可能仍然要面对欠债，道馆也还是会倒闭。那我回去干什么？」"], "choices": [{"t": "「继续活。」「活下去不是答案。活下去以后，才会有答案。」", "go": "seven_done", "fx": {"wisdom": 1, "human": 1}}, {"t": "「因为你答应过那个小女孩，道馆要重新开门。」", "go": "seven_done", "fx": {"human": 2}, "req": {"flag": "turtle"}}, {"t": "「我不知道。你自己想。」", "go": "seven_done", "fx": {"wisdom": 1}}], "art": "four_farewells"}, "seven_done": {"bg": "shanmoon_core", "text": ["六个人都消失了。山洞里只剩下你们的呼吸，和一颗越来越慢的黑色心脏。", "「他们没有被删除。因为钥匙锁住的不是时间。」你说，「是后悔。只要他们不再要求重来，时间便会放他们回去。」", "晏归迟脸上的平静终于维持不住：「荒谬。人不可能放下后悔。」「他们没有放下。只是决定不再听你指挥。」", "他的身体开始变淡。", "「你以为这样就赢了？你只有六把钥匙。第七把在你身上。」", "你低头。胸口的半月形光芒还在。第七把钥匙没有出现——因为你仍然后悔。", "「你叫别人接受人生很容易。轮到自己呢？你真的接受过去六年？接受放弃跆拳道？接受错过朋友？接受让母亲一次次等你？只要还有一件事想改变，第七把钥匙便不会离开。」", "「剩余时间：九分钟。」"], "choices": [{"t": "承认：「我放不下后悔。」", "go": "final_choice", "fx": {"human": 1}}, {"t": "说谎：「我不后悔。」", "go": "final_choice", "fx": {"regret": 1}, "hint": "阿月说过：有时候说谎也可以救人。「山月盘知道。」"}], "art": "six_leave"}, "final_choice": {"bg": "shanmoon_core", "title": "终局 · 谁作决定", "text": ["「晏归迟说得对。」你听见自己说，「我放不下后悔。」", "他的笑容回来了：「所以你没有资格——」", "「但我也不需要放下。」你打断他，「后悔不是错误。是它让我知道，下一次应该怎样选择。如果完全没有后悔，我今天不会回去救阿月，也不会回家陪母亲吃饭。」", "要消灭晏归迟，并不是让自己从此不再后悔。那不可能。人只要活着，便会不断选择；只要选择，便一定失去另一种可能。", "真正的问题从来不是有没有遗憾。而是——谁作决定。", "你走向他。影子暴涨，无数黑色手臂从地面伸出。阿月拔刀，段云生从岩石下挣脱，阿月父亲用身体压住山月盘的裂缝：「不要让黑影碰到山月核！」", "「你接受我，就会拥有六条人生全部痛苦！母亲死亡的每一秒！女儿离开的每一个眼神！破产！背叛！失败！你会在十八岁，承受六个人一生的重量！」", "你继续向前走。「我知道。」「你会疯！」「可能。」「你会变成我！」「不会。」", "为什么？"], "choices": [{"t": "「因为我不是一个人。你只有自己。我还有他们。」", "go": "embrace", "fx": {"human": 1, "trustA": 1}}, {"t": "「因为我还有你。」", "go": "embrace", "fx": {"courage": 1, "wisdom": 1, "flags": {"accept_shadow": 1}}}, {"t": "停下。你想起病房里的十七通未接来电", "go": "embrace", "fx": {"human": 1}, "req": {"flag": "named"}, "hint": "你回头看了阿月、段云生、阿月父亲，最后看向他"}], "art": "shadow_arms"}, "embrace": {"bg": "shanmoon_core", "text": ["他猛然伸手，五指刺进你的胸口。没有鲜血，只有无数记忆涌入。", "你没有躲。你抱住了他——像抱住一个疲倦、愤怒而无处可去的老人。", "「回家吧。」", "这三个字，他等了很多年。「哪里是家？」「我也不知道。先一起回去再说。」", "「如果你变成我呢？」「阿月会打醒我。」", "正在与黑影搏斗的阿月抽空回答：「会。」", "他笑了。第一次不是冷笑，也不是讽刺，只是一个很普通的笑容。「那可能很痛。」「她下手一直很重。」", "他闭上眼睛，化成一道黑暗，进入你的胸口。", "六条人生的后悔同时压下来。你跪倒在地，几乎无法呼吸。", "阿月冲过来抓住你的肩膀：「你是谁？」你抬起头，眼神苍老得不像十八岁。", "她扬起手，一巴掌打在你脸上。啪。很响。「你真的打？」「你叫我打醒你。」「也不用这么快。」「现在你是谁？」"], "choices": [{"t": "回答她", "go": "key_eight"}], "art": "embrace_shadow"}, "key_eight": {"bg": "shanmoon_core", "text": ["「杨小天。」「哪个杨小天？」「第七个。」「错。」", "她指向你胸口。第七把月钥正在缓缓浮出。上面的数字不是七——", "是八。", "阿月父亲靠着破裂的山月盘，露出微笑：「因为你作出了前七个都没有作出的选择。你没有消灭后悔，也没有服从后悔。山月盘出现了从未保存过的时间。第八条路。」", "第八把月钥飞向半空，前六把同时靠近，最后，一号与七号组成的圆形铜牌也从你胸前出现。七道光汇聚，全部投入山月核。", "黑石出现第一道裂纹。然后第二道。第三道。山洞外的风突然停止。", "「删除程序终止。时间归还。山月核心即将瓦解。剩余时间：十八秒。」", "「十八秒？怎么突然变得这么少？」「时间已经重新分开。」"], "choices": [{"t": "两道门出现了", "go": "final_goodbye"}], "art": "key_eight_art"}, "final_goodbye": {"bg": "ending_buchi", "title": "抉择 · 最后一次", "art": "two_doors", "text": ["石室中出现两道门。左边门后，是2026年的沐山月民宿；右边门后，是1450年的大理古城。两个世界正在迅速远离。", "阿月扶起父亲。男人没有动——胸口的青铜碎片插得很深，每一次呼吸都有鲜血涌出。", "「我走不了。」「我背你。」「阿月。你以前答应过，要带我去看海。」「你还没有带我去。」", "他伸手摸了摸她的头，双手仍然扭曲，动作却很温柔：「是爹迟了。」", "段云生走过来：「我留下。」「你留下有什么用？」「我欠你父亲一条命。」阿月父亲摇头：「我不要你的命。把阿月带走。带去哪里？她自己选。」", "左边是现代：汽车、飞机、电灯、医院，还有她一直想看的海。右边是景泰元年的大理：贫穷、危险、尚未发生的追杀，也是她出生和成长的世界。", "「十二秒。」"], "choices": [{"t": "拉住阿月：「跟我去2026年。历史没有你也会继续。」", "go": "she_chooses", "fx": {"human": 1}}, {"t": "对阿月说：「你自己选。我不替你回答。」", "go": "she_chooses", "fx": {"wisdom": 1, "human": 1, "trustA": 1}}, {"t": "什么都说不出口", "go": "she_chooses", "fx": {"regret": 1}}, {"t": "停下。你既不进左边的门，也不追右边的门——你走向阿月父亲，接过他手上的铁锤", "note": "「还有一些事可以做对。」你听见段云生说的话，忽然明白那句话也可以由你来说", "req": {"stat": {"human": ">=6"}}, "fx": {"flags": {"stay_1450": 1}}, "end": "E7"}]}, "she_chooses": {"bg": "ending_buchi", "text": ["阿月向左走了一步，又停下。「如果我去了，你呢？」", "父亲没有回答。她已经知道答案。", "山月核完全破裂，白光开始吞没石室。「八秒。」", "她忽然推了你一把。", "你跌进左边的现代之门。「阿月！」你伸手，只抓到半截衣袖。布料撕裂。她退回右边。", "「你做什么？」「回家。」「那不是回家！」「对你不是。对我是。」", "「五秒。」段云生走向右边：「我陪她回去。」", "「我还没有原谅你。」「我知道。也可能永远不会。」「我知道。」「那你为什么跟来？」", "他看了一眼年轻的自己所在的年代：「还有一些事可以做对。」", "他扶起阿月父亲，三人一起走向1450年。门后的力量把你拉向现代。", "「杨小天！」她最后喊了一声。", "「替我看看海。」「你可以自己来看！」「也许以后。」「什么时候？」", "「等我不用穿过时间。」", "白光越来越强，你已经看不清她的脸。", "「不要再让别人等你！」", "两道时间同时关闭。最后一秒，她扔过来一样东西。你伸手接住——半月形铜牌，上面没有数字，只刻着两个字：", "「不迟。」"], "choices": [{"t": "把「不迟」收进内袋，回到2026", "go": "epilogue", "fx": {"flags": {"buchi": 1}}}, {"t": "隔着关闭的门，喊了一句什么——连你自己都不知道是什么", "go": "epilogue", "fx": {"flags": {"buchi": 1}}}], "art": "torn_sleeve"}, "epilogue": {"bg": "ending_buchi", "title": "终章 · 十点四十三分", "text": ["山月核彻底破碎。所有声音消失。", "你重重摔在现代民宿的院子里。院中的梅树被风吹动。手机时间从十点四十二分，跳到十点四十三分。", "民宿大门外仍然是热闹的步行街。没有人知道，三条时间刚刚差点一起消失。", "你爬起来。院子里没有阿月，没有段云生，柜台后也没有那个年轻女孩。整间民宿一片漆黑：桌面积满灰尘，墙皮脱落，门窗腐朽——不像荒废了十几年，更像已经几百年没有人住过。", "手机电量只剩百分之一。手电筒的光扫过柜台后的墙壁——没有黑白照片，只有一块刻满文字的石碑。", "最上方写着：沐山驿记。落款：景泰三年，公元1452年。", "碑文记载：景泰元年，大理曾经发生一次无人能够解释的「失时之夜」。数十人在同一条街上消失，翌日重新出现时，所有人都失去十八分钟记忆。", "碑文最后提到三个人：一个姓段的少女。一个断了小指的军士。一个来自「香江」的少年。", "石碑最下面，有一行后来加上去的小字。字迹和阿月一模一样：", "「杨小天，我已经看过海了。比你说的还要大。」", "手机电量归零。光熄灭。", "黑暗中，民宿二楼传来脚步声。一步。一步。", "有人从已经不存在的七号房走出来，用你的声音问：", "「第八个。你真的以为——我们已经回家了吗？」", "……", "（第二天中午，你在昆明转机回港。候机的时候，你把A/B/C方案全部删掉了，重新填了一份没有概率的旅行计划：大学报到以前，看完海。", "三个月后，你的成绩中等偏好。不够进最想进的那间，但够进另一间也不错的。", "没有人知道那一晚发生过什么。你自己也开始怀疑它是不是真的。", "只有两样东西提醒你：手腕上一道被火烫过的旧疤；和内袋里一块刻着「不迟」的铜牌。", "—— 剧终 ——"], "choices": [{"t": "完成本周目", "end": "GOOD_END"}], "art": "stone_tablet"}}, "endings": {"E0": {"title": "坏结局 · 理智的选择", "art": "washroom_mirror", "text": ["你转身离开洗手间，回民宿，睡觉。第二天继续旅行，回香港，出成绩，上大学，做一份「有前途」的工作。", "一切都很正常。正常得像那条没有多停留一秒的时间线。", "很多年后，你在机场洗手间洗手，镜子的背景闪了一下。", "你太累了，没有再看第二眼。", "——但有人替你看了。那个人浑身是血，从一条十五世纪的巷子冲出来，抓住一个十八岁少年的肩膀：「终于……来了。」", "第七次，从来不会取消。它只会换一个人来赴约。"]}, "E1": {"title": "坏结局 · 第三十七次心跳", "art": "alley_riders", "text": ["刀落下去的时候，你想起的不是DSE，不是黑带，也不是母亲那五条信息。", "你想的是那朵枯萎的玫瑰——二十元，毫无用途，不能增加任何录取概率。", "景泰元年的泥地上，一个十八岁的香港少年死在巷口。马蹄声远去。", "很多年后，会有另一个杨小天在洗手间捡起一张身份证，看见照片上与自己相同的出生日期。", "「这是第七次。」", "——不。很快，就是第八次了。"]}, "E2": {"title": "坏结局 · 历史没有改变", "art": "burning_inn", "text": ["你和前面六个自己，作出了同样的选择。", "晏归迟没有嘲笑你。他甚至看起来松了一口气——像一份被反复核对的账目终于对上了。", "后来的六次逃亡、六次火灾、六次七号房，你都经历了一遍，每次都差一点，每次都「讲逻辑」。", "铜镜最喜欢想回家的人。它让你回家。", "2056年，病房，十七通未接来电。电子钟永远停在十点四十二分。", "你已经在这里了。你只是还不记得。"]}, "E3": {"title": "坏结局 · 沉没成本", "art": "washroom_mirror", "text": ["你留在现代。青铜门在阿月眼前关闭。", "你确实「理性」：不救一个五百多年前的人，救一个活生生的自己。这个决定在任何一个评分标准里都是满分。", "三个月后成绩公布，你进了最想进的大学。四年后毕业。七年后升职。", "只是从那天起，你无法照镜子。洗手间的灯、滴水的水龙头、婚纱、半月形的月亮，都会在某一个瞬间，从视野边缘慢慢爬进来。", "医生说是创伤后应激。药很好吃。海很大。", "二十年后，你在苍山脚下租了一间旧驿馆，把招牌改成三个字：沐山月。", "你在等一个人查入住记录。你说不清是等她，还是等那把刀。"]}, "E4": {"title": "坏结局 · 商量好的迟到", "art": "yanguichi", "text": ["你们退出了门。你们商量了一整夜。你们考虑了风险、路线、情报、备选方案。", "你们考虑得很周全。", "第二天清晨推开七号房的门，门后只剩下沐山驿的废墟和一地冷灰。晏归迟不见了，山月盘自己去了苍山深处——它不需要再等谁。", "删除程序在没有任何人见证的情况下启动。", "1450年的大理，一整条街的人在同一天忘记了十八分钟。2056年的病房，心电监护仪的长鸣第一次没有被打断。", "你活下来了。你只是没有参与。", "——记住：门会在那里。但不会永远在那里。"]}, "E5": {"title": "坏结局 · 标准答案", "art": "hospital_2056", "text": ["条形码贴上的一瞬，礼堂、课桌、无脸考生，全部消失。", "你站在2056年的病房里。心电监护仪发出长鸣，床上躺着你的母亲。", "你终于「拥有」了所有正确答案：最理想的大学、最有前途的专业、足够的钱、完整的人生履历。", "只是——那是别人的答案。你的母亲在等你回家，而你已经学会了用「以后」回答她。", "墙上的电子钟：2056年7月19日，晚上10点42分。秒数，没有跳动。", "你会在这里，把这条人生，再考一次。"]}, "E6": {"title": "坏结局 · 完美人生", "art": "blood_mirror", "text": ["你说：好，我接受。", "六条人生的记忆同时涌入：每一种成功、每一次失败、每一个后悔。你全部避开了。", "你也全部没有经历过。", "2026年的香港，有一个履历完美得可怕的年轻人。他知道自己会在哪一天失去母亲、哪一年破产、爱错哪一个人——于是他绕开了所有事，包括所有值得爱的事。", "没有人可以骗他。也没有人愿意靠近他。", "晏归迟拿走第七块月钥时，只留下一句话：「看，你连后悔的机会都没有了。」"]}, "GOOD_END": {"title": "真結局 · 第八條路", "art": "ending_buchi", "good": true, "text": ["你帶著一塊刻着「不遲」的銅牌，回到沒有任何人知道發生過什麼的2026年。", "這不是你一個人贏下來的結局——它在等你自己走到那扇門前，然後，選擇不進去。", "（通關後可查看：本週目數據、已解鎖結局、與你做出相同選擇的楊小天比例。）"]}, "E7": {"title": "隐藏结局 · 第十二年的钥匙", "art": "duan_yunsheng", "text": ["你没有回2026，也没有追着阿月回1450。", "景泰元年的大理，城门在黎明封锁，沐山驿大火未熄。你替阿月父亲扶住了最后一段山月盘的裂缝。", "段云生看着你：「你知道留下来意味着什么。」", "你知道。一个来自香江的少年，会在十五世纪学会生火、赶马、染布，会守一间驿馆，会用十二年，把「对不起」三个字练到不怕烫。", "第十二年，你会在2014年打开山月门。你会带回一个六十二岁、重伤的病人。你会在他床前听完那个关于「回到阿月父亲被捕以前」的谎言，然后照做——因为你终于懂了他为什么做。", "阿月每年清明都会来梅树下坐一会儿。她不知道树下的另一个坟，埋的是谁的将来。", "（你解锁了段云生的一生。沐山驿记碑文的最后一行，多了一个名字。", " 字迹是新的。落款：「不迟」。）"]}}, "stats": {"courage": "勇氣 · 你敢不敢", "wisdom": "智慧 · 你信不信得快", "human": "人性 · 你还记不记得汤", "regret": "後悔 · 山月盤的食物", "trustA": "羈絆 · 阿月信你幾多", "suspA": "警覺 · 你幾時開始懷疑晏歸遲"}};